        SlicerOption(key: "seam_position", page: "Qualität", group: "Naht", kind: .choice, title: "Nahtposition", summary: "Die Startposition für den Druck jedes Teils der Außenwand", unit: "", min: nil, max: nil, choices: [("nearest", "Nächste"), ("aligned", "Ausgerichtet"), ("aligned_back", "Ausgerichtet hinten"), ("back", "Rückseite"), ("random", "Zufall")], availableFor: [.kobraS1, .snapmakerU1], vendor: [.kobraS1: "aligned", .snapmakerU1: "aligned"]),
        SlicerOption(key: "staggered_inner_seams", page: "Qualität", group: "Naht", kind: .bool, title: "Versetzte innere Nähte", summary: "Durch diese Option werden die inneren Nähte basierend auf ihrer Tiefe nach hinten verschoben und bilden ein Zickzack-Muster.", unit: "", min: nil, max: nil, choices: [], availableFor: [.kobraS1, .snapmakerU1], vendor: [.kobraS1: "0"]),
        SlicerOption(key: "seam_gap", page: "Qualität", group: "Naht", kind: .floatOrPercent, title: "Nahtlücke", summary: "Um die Sichtbarkeit der Naht in einer geschlossenen Schleifenextrusion zu reduzieren, wird die Schleife unterbrochen und um eine bestimmte Menge verkürzt.\nDiese Menge kann in Millimetern oder als Prozentsatz des aktuellen Extruderdurchmessers angegeben werden.\nDer Standardwert für diesen Parameter beträgt 10%. Dies wird durchgeführt, um das endgültige Produkt glatter und nahtloser aussehen zu lassen.", unit: "mm oder %", min: 0.0, max: nil, choices: [], availableFor: [.kobraS1, .snapmakerU1], vendor: [.kobraS1: "10%"]),
        SlicerOption(key: "seam_slope_type", page: "Qualität", group: "Naht", kind: .choice, title: "Schrägnaht (Scarf Joint, Beta)", summary: "Benutze die Schrägnaht um die Sichtbarkeit der Naht zu minimieren und die Nahtstärke zu erhöhen.", unit: "", min: nil, max: nil, choices: [("none", "Keine"), ("external", "Kontur"), ("all", "Kontur und Loch")], availableFor: [.kobraS1, .snapmakerU1], vendor: [.kobraS1: "none"]),
        SlicerOption(key: "seam_slope_conditional", page: "Qualität", group: "Naht", kind: .bool, title: "Schrägnaht nur bei Bedarf", summary: "Wenden Sie Schrägnähte nur auf glatte Umfänge an, bei denen traditionelle Nahtstellen die Nähte an scharfen Ecken nicht effektiv verbergen.", unit: "", min: nil, max: nil, choices: [], availableFor: [.kobraS1, .snapmakerU1], vendor: [.kobraS1: "1"]),
        SlicerOption(key: "scarf_angle_threshold", page: "Qualität", group: "Naht", kind: .int, title: "Schrägnaht: Winkelschwelle", summary: "Diese Option legt den Schwellenwinkel für das Anwenden einer bedingten Schrägnaht fest.\nWenn der maximale Winkel innerhalb der Umfangsschleife diesen Wert überschreitet (was auf das Fehlen von scharfen Ecken hinweist), wird eine Schrägnaht verwendet. Der Standardwert beträgt 155°.", unit: "", min: 0.0, max: 180.0, choices: [], availableFor: [.kobraS1, .snapmakerU1], vendor: [.kobraS1: "155"]),
        SlicerOption(key: "scarf_overhang_threshold", page: "Qualität", group: "Naht", kind: .percent, title: "Schrägnaht: Überhang-Schwelle", summary: "Diese Option bestimmt den Überhangsschwellenwert für die Anwendung von Schrägnahtnähten. Wenn der nicht unterstützte Teil des Umfangs kleiner als dieser Schwellenwert ist, werden Schrägnahtnähte angewendet. Der Standardwert für die Schwelle beträgt 40% der Breite der äußeren Wand. Auf Grund von Leistungserwägungen wird der Grad des Überhangs geschätzt.", unit: "", min: 0.0, max: nil, choices: [], availableFor: [.kobraS1, .snapmakerU1], vendor: [.kobraS1: "40%"]),
        SlicerOption(key: "scarf_joint_speed", page: "Qualität", group: "Naht", kind: .floatOrPercent, title: "Schrägnaht: Geschwindigkeit", summary: "Diese Option legt die Druckgeschwindigkeit für Schrägnähte fest. Es wird empfohlen, Schrägnähte mit einer langsamen Geschwindigkeit (weniger als 100 mm/s) zu drucken. Es ist auch ratsam, die 'Glättung der Extrusionsrate' zu aktivieren, wenn die eingestellte Geschwindigkeit erheblich von der Geschwindigkeit der äußeren oder inneren Wände abweicht. Wenn die hier angegebene Geschwindigkeit höher ist als die Geschwindigkeit der äußeren oder inneren Wände, wird der Drucker auf die langsamere der beiden Geschwindigkeiten zurückgesetzt. Wenn sie als Prozentsatz angegeben wird (z.B. 80%), wird die Geschwindigkeit auf der Grundlage der jeweiligen Geschwindigkeit der äußeren oder inneren Wand berechnet. Der Standardwert ist auf 100% eingestellt.", unit: "mm/s oder %", min: 1.0, max: nil, choices: [], availableFor: [.kobraS1, .snapmakerU1], vendor: [.kobraS1: "30"]),
        SlicerOption(key: "seam_slope_start_height", page: "Qualität", group: "Naht", kind: .floatOrPercent, title: "Schrägnaht: Starthöhe", summary: "Start Höhe der Schrägnaht.\nDiese Menge kann in Millimetern oder als Prozentsatz der aktuellen Schichthöhe angegeben werden.\nDer Standardwert für diesen Parameter beträgt 0.", unit: "mm oder %", min: 0.0, max: nil, choices: [], availableFor: [.kobraS1, .snapmakerU1], vendor: [.kobraS1: "10%"]),
        SlicerOption(key: "seam_slope_entire_loop", page: "Qualität", group: "Naht", kind: .bool, title: "Schrägnaht über die ganze Wand", summary: "Die Schrägnaht erstreckt sich über die gesamte Länge der Wand.", unit: "", min: nil, max: nil, choices: [], availableFor: [.kobraS1, .snapmakerU1], vendor: [.kobraS1: "0"]),
        SlicerOption(key: "seam_slope_min_length", page: "Qualität", group: "Naht", kind: .float, title: "Schrägnaht: Mindestlänge", summary: "Länge der Schrägnaht. Das Einstellen dieses Parameters auf Null deaktiviert effektiv die Schrägnaht.", unit: "mm", min: 0.0, max: nil, choices: [], availableFor: [.kobraS1, .snapmakerU1], vendor: [.kobraS1: "10"]),
        SlicerOption(key: "seam_slope_steps", page: "Qualität", group: "Naht", kind: .int, title: "Schrägnaht: Anzahl Stufen", summary: "Mindestanzahl von Segmenten jeder Schrägnaht.", unit: "", min: 1.0, max: nil, choices: [], availableFor: [.kobraS1, .snapmakerU1], vendor: [.kobraS1: "10"]),
        SlicerOption(key: "scarf_joint_flow_ratio", page: "Qualität", group: "Naht", kind: .float, title: "Schrägnaht: Fluss", summary: "Dieser Faktor beeinflusst die Menge an Material für Schrägnähte.", unit: "", min: nil, max: 2.0, choices: [], availableFor: [.kobraS1, .snapmakerU1], vendor: [.kobraS1: "1"]),
        SlicerOption(key: "seam_slope_inner_walls", page: "Qualität", group: "Naht", kind: .bool, title: "Schrägnaht auch für Innenwände", summary: "Verwenden Sie Schrägnaht auch für innere Wände.", unit: "", min: nil, max: nil, choices: [], availableFor: [.kobraS1, .snapmakerU1], vendor: [.kobraS1: "1"]),
        SlicerOption(key: "role_based_wipe_speed", page: "Qualität", group: "Naht", kind: .bool, title: "Abwischtempo nach Wandart (Wipe)", summary: "Die Wischengeschwindigkeit wird durch die Geschwindigkeit der aktuellen Extrusion bestimmt.\nz.B. wenn eine Wischenaktion unmittelbar nach einer äußeren Wand-Extrusion ausgeführt wird, wird die Geschwindigkeit der äußeren Wand-Extrusion für die Wischenaktion verwendet.", unit: "", min: nil, max: nil, choices: [], availableFor: [.kobraS1, .snapmakerU1], vendor: [.kobraS1: "1"]),
        SlicerOption(key: "wipe_speed", page: "Qualität", group: "Naht", kind: .floatOrPercent, title: "Abwischtempo (Wipe)", summary: "Die Wischengeschwindigkeit wird durch die im Konfigurationsmenü angegebene Geschwindigkeit bestimmt.Wenn der Wert als Prozentsatz (z.B. 80%) angegeben ist, wird er aufgrund der oben angegebenen Reisegeschwindigkeit berechnet. Der Standardwert für diesen Parameter beträgt 80%", unit: "mm/s oder %", min: 0.0, max: nil, choices: [], availableFor: [.kobraS1, .snapmakerU1], vendor: [.kobraS1: "80%"]),
        SlicerOption(key: "wipe_on_loops", page: "Qualität", group: "Naht", kind: .bool, title: "Abwischen nach innen (Wipe on Loops)", summary: "Um die Sichtbarkeit der Naht in einer geschlossenen Schleifen-Extrusion zu minimieren, wird vor dem Verlassen der Schleife eine kleine Bewegung nach innen ausgeführt.", unit: "", min: nil, max: nil, choices: [], availableFor: [.kobraS1, .snapmakerU1], vendor: [.kobraS1: "0"]),
        SlicerOption(key: "wipe_before_external_loop", page: "Qualität", group: "Naht", kind: .bool, title: "Abwischen vor der Außenwand", summary: "Um die Sichtbarkeit einer möglichen Überextrusion am Anfang eines äußeren Umfangs zu minimieren, wenn mit der Druckreihenfolge \"Außen/Innen\" oder \"Innen/Außen/Innen\" gedruckt wird, wird der Rückzug etwas nach innen vom Anfang des äußeren Umfangs ausgeführt. Auf diese Weise wird eine mögliche Überextrusion von der Außenfläche verdeckt.\n\nDies ist nützlich, wenn mit der Druckreihenfolge \"Außen/Innen\" oder \"Innen/Außen/Innen\" gedruckt wird, da in diesen Modi ein äußerer Umfang unmittelbar nach einem Rückzug gedruckt wird.", unit: "", min: nil, max: nil, choices: [], availableFor: [.kobraS1, .snapmakerU1], vendor: [.kobraS1: "0"]),
        SlicerOption(key: "slice_closing_radius", page: "Qualität", group: "Präzision", kind: .float, title: "Lückenschlussradius beim Slicen", summary: "Risse, die kleiner als das 2-fache des Lückenschlussradius sind, werden beim Slicen des Modellnetzes gefüllt. Der Vorgang des Lückenschließens kann die endgültige Druckauflösung verringern, daher ist es ratsam, den Wert relativ niedrig zu halten.", unit: "mm", min: 0.0, max: nil, choices: [], availableFor: [.kobraS1, .snapmakerU1], vendor: [.kobraS1: "0.049"]),
        SlicerOption(key: "resolution", page: "Qualität", group: "Präzision", kind: .float, title: "Auflösung (Toleranz der Kontur)", summary: "Der G-Code-Pfad wird nach der Vereinfachung der Kontur des Modells generiert, um zu viele Punkte und G-Code Befehle in der G-Code-Datei zu vermeiden. Ein kleinerer Wert bedeutet eine höhere Auflösung und mehr Zeit zum Slicen.", unit: "", min: 0.0, max: nil, choices: [], availableFor: [.kobraS1, .snapmakerU1], vendor: [.kobraS1: "0.012", .snapmakerU1: "0.012"]),
        SlicerOption(key: "enable_arc_fitting", page: "Qualität", group: "Präzision", kind: .bool, title: "Arc Fitting (Bögen statt Strecken)", summary: "Aktivieren Sie diese Option, um eine G-Code-Datei zu erhalten, die G2- und G3-Bewegungen enthält. Die Passungstoleranz entspricht der Auflösung.\n\nHinweis: Für Klipper-Maschinen wird empfohlen, diese Option zu deaktivieren. Klipper profitiert nicht von Bogenbefehlen, da diese von der Firmware wieder in Linienabschnitte aufgeteilt werden. Dies führt zu einer Verringerung der Oberflächenqualität, da Linienabschnitte vom Slicer in Bögen umgewandelt und dann von der Firmware wieder in Linienabschnitte umgewandelt werden.", unit: "", min: nil, max: nil, choices: [], availableFor: [.kobraS1, .snapmakerU1], vendor: [.kobraS1: "0", .snapmakerU1: "1"]),
        SlicerOption(key: "xy_hole_compensation", page: "Qualität", group: "Präzision", kind: .float, title: "Loch-Korrektur XY", summary: "Die Löcher des Objekts werden in der XY-Ebene um den eingestellten Wert vergrößert oder verkleinert. Ein positiver Wert macht die Löcher größer, ein negativer Wert macht die Löcher kleiner. Diese Funktion wird verwendet, um die Größe geringfügig anzupassen, wenn Objekte Montageprobleme haben.", unit: "mm", min: nil, max: nil, choices: [], availableFor: [.kobraS1, .snapmakerU1], vendor: [.kobraS1: "0", .snapmakerU1: "0"]),
        SlicerOption(key: "xy_contour_compensation", page: "Qualität", group: "Präzision", kind: .float, title: "Konturkorrektur XY", summary: "Die Kontur von Objekten wird in der XY-Ebene um den eingestellten Wert vergrößert oder verkleinert. Positive Werte vergrößern Konturen, negative Werte verkleinern Konturen. Diese Funktion wird verwendet, um die Größe geringfügig anzupassen, wenn Objekte Probleme bei der Montage haben.", unit: "mm", min: nil, max: nil, choices: [], availableFor: [.kobraS1, .snapmakerU1], vendor: [.kobraS1: "0", .snapmakerU1: "0"]),
        SlicerOption(key: "elefant_foot_compensation", page: "Qualität", group: "Präzision", kind: .float, title: "Elefantenfuß-Ausgleich", summary: "Verkleinert die erste Schicht auf dem Druckbett, damit der „Elefantenfuß“ (ausgequetschter Rand an der Unterseite) die Maße nicht verfälscht.", unit: "mm", min: 0.0, max: nil, choices: [], availableFor: [.kobraS1, .snapmakerU1], vendor: [.kobraS1: "0.1", .snapmakerU1: "0.15"]),
        SlicerOption(key: "elefant_foot_compensation_layers", page: "Qualität", group: "Präzision", kind: .int, title: "Elefantenfuß-Ausgleich: Anzahl Schichten", summary: "Die Anzahl der Schichten, in denen die Elefantenfußkompensation aktiv ist. Die erste Schicht wird um den Wert der Elefantenfußkompensation verkleinert, dann werden die nächsten Schichten linear weniger verkleinert, bis zur Schicht, die durch diesen Wert angegeben ist.", unit: "Schichten", min: 1.0, max: nil, choices: [], availableFor: [.kobraS1, .snapmakerU1], vendor: [.kobraS1: "1"]),
        SlicerOption(key: "precise_outer_wall", page: "Qualität", group: "Präzision", kind: .bool, title: "Präzise Außenwand", summary: "Verbessern Sie die Schalengenauigkeit, indem Sie den Abstand der äußeren Wand anpassen. Dies verbessert auch die Konsistenz der Schichten. HINWEIS: Diese Option wird für Außen-Innen- oder Innen-Außen-Innen-Wand-Sequenzen ignoriert.", unit: "", min: nil, max: nil, choices: [], availableFor: [.kobraS1, .snapmakerU1], vendor: [.kobraS1: "0"]),
        SlicerOption(key: "precise_z_height", page: "Qualität", group: "Präzision", kind: .bool, title: "Präzise Z-Höhe", summary: "Aktivieren Sie diese Option, um die genaue Z-Höhe des Objekts nach dem Slicen zu erhalten. Es wird die genaue Objekthöhe durch Feinabstimmung der Schichthöhen der letzten Schichten erhalten. Beachten Sie, dass dies ein experimenteller Parameter ist.", unit: "", min: nil, max: nil, choices: [], availableFor: [.kobraS1, .snapmakerU1], vendor: [.kobraS1: "0"]),
        SlicerOption(key: "hole_to_polyhole", page: "Qualität", group: "Präzision", kind: .bool, title: "Löcher als Polyhole drucken", summary: "Suchen Sie nach fast kreisförmigen Löchern, die sich über mehr als eine Schicht erstrecken, und konvertieren Sie die Geometrie in Polyholes. Verwenden Sie die Düsengröße und den (größten) Durchmesser, um das Polyhole zu berechnen.\nSiehe http://hydraraptor.blogspot.com/2011/02/polyholes.html", unit: "", min: nil, max: nil, choices: [], availableFor: [.kobraS1, .snapmakerU1], vendor: [.kobraS1: "0"]),
        SlicerOption(key: "hole_to_polyhole_threshold", page: "Qualität", group: "Präzision", kind: .floatOrPercent, title: "Polyhole: Schwelle", summary: "Maximale Abweichung eines Punktes vom geschätzten Radius des Kreises.\nDa Zylinder oft als Dreiecke unterschiedlicher Größe exportiert werden, liegen die Punkte möglicherweise nicht auf dem Umfang des Kreises. Diese Einstellung ermöglicht es Ihnen, die Erkennung zu erweitern.\nIn mm oder in % des Radius.", unit: "mm oder %", min: nil, max: nil, choices: [], availableFor: [.kobraS1, .snapmakerU1], vendor: [.kobraS1: "0.01"]),
        SlicerOption(key: "hole_to_polyhole_twisted", page: "Qualität", group: "Präzision", kind: .bool, title: "Polyhole verdreht", summary: "Polyhole in jeder Schicht drehen.", unit: "", min: nil, max: nil, choices: [], availableFor: [.kobraS1, .snapmakerU1], vendor: [.kobraS1: "1"]),
        SlicerOption(key: "ironing_type", page: "Qualität", group: "Glätten", kind: .choice, title: "Bügeln (Ironing)", summary: "Beim Glätten wird ein kleiner Fluss verwendet, um die gleiche Höhe der Oberfläche erneut zu bedrucken und die Oberfläche glatter zu machen. Diese Einstellung steuert, welche Schicht geglättet wird", unit: "", min: nil, max: nil, choices: [("no ironing", "Kein Glätten"), ("top", "Obere Oberflächen"), ("topmost", "Oberste Oberfläche"), ("solid", "All solid layer")], availableFor: [.kobraS1, .snapmakerU1], vendor: [.kobraS1: "no ironing", .snapmakerU1: "no ironing"]),
        SlicerOption(key: "ironing_pattern", page: "Qualität", group: "Glätten", kind: .choice, title: "Bügeln: Muster", summary: "Das Muster, das beim Glätten verwendet wird", unit: "", min: nil, max: nil, choices: [("rectilinear", "Geradlinig"), ("concentric", "Konzentrisch")], availableFor: [.kobraS1, .snapmakerU1], vendor: [.kobraS1: "zig-zag"]),
        SlicerOption(key: "ironing_speed", page: "Qualität", group: "Glätten", kind: .float, title: "Bügeln: Geschwindigkeit", summary: "Druckgeschwindigkeit der Glättlinien.", unit: "mm/s", min: 1.0, max: nil, choices: [], availableFor: [.kobraS1, .snapmakerU1], vendor: [.kobraS1: "30", .snapmakerU1: "30"]),
        SlicerOption(key: "ironing_flow", page: "Qualität", group: "Glätten", kind: .percent, title: "Bügeln: Fluss", summary: "Die Materialmenge, die während des Glättens extrudiert wird. Dies ist relativ zum Fluss der normalen Schichthöhe. Ein zu hoher Wert führt zu einer Überextrusion der Oberfläche.", unit: "", min: 0.0, max: 100.0, choices: [], availableFor: [.kobraS1, .snapmakerU1], vendor: [.kobraS1: "10%", .snapmakerU1: "10%"]),
        SlicerOption(key: "ironing_spacing", page: "Qualität", group: "Glätten", kind: .float, title: "Bügeln: Linienabstand", summary: "Der Abstand zwischen den Linien beim Glätten", unit: "mm", min: 0.0, max: 1.0, choices: [], availableFor: [.kobraS1, .snapmakerU1], vendor: [.kobraS1: "0.15", .snapmakerU1: "0.15"]),
        SlicerOption(key: "ironing_inset", page: "Qualität", group: "Glätten", kind: .float, title: "Bügeln: Abstand zum Rand", summary: "Der Abstand zu den Kanten. Ein Wert von 0 setzt dies auf die Hälfte des Düsendurchmessers.", unit: "mm", min: 0.0, max: 100.0, choices: [], availableFor: [.kobraS1, .snapmakerU1], vendor: [:]),
        SlicerOption(key: "ironing_angle", page: "Qualität", group: "Glätten", kind: .float, title: "Bügeln: Winkel", summary: "Der Winkel, in dem das Glätten durchgeführt wird. Eine negative Zahl deaktiviert diese Funktion und verwendet die Standardmethode.", unit: "", min: -1.0, max: 359.0, choices: [], availableFor: [.kobraS1, .snapmakerU1], vendor: [.kobraS1: "-1"]),
        SlicerOption(key: "wall_generator", page: "Qualität", group: "Wandgenerator", kind: .choice, title: "Wandgenerator (Arachne / Klassisch)", summary: "Der klassische Wandgenerator erzeugt Wände mit konstanter Extrusionsbreite, wobei für sehr dünne Bereiche die Lückenfüllung verwendet wird. Die Arachne-Engine erzeugt Wände mit variabler Extrusionsbreite.", unit: "", min: nil, max: nil, choices: [("classic", "Klassisch"), ("arachne", "Arachne")], availableFor: [.kobraS1, .snapmakerU1], vendor: [.kobraS1: "classic", .snapmakerU1: "arachne"]),
        SlicerOption(key: "wall_transition_angle", page: "Qualität", group: "Wandgenerator", kind: .float, title: "Wandübergang: Schwellenwinkel", summary: "Wenn Übergänge zwischen einer geraden und einer ungeraden Anzahl von Wänden erstellt werden sollen. Eine Keilform mit einem größeren Winkel als dieser Einstellung hat keine Übergänge und es werden keine Wände in der Mitte gedruckt, um den verbleibenden Raum zu füllen. Wenn Sie diese Einstellung verringern, wird die Anzahl und Länge der mittleren Wände reduziert, was jedoch Lücken oder Überextrusion verursachen kann.", unit: "", min: 1.0, max: 59.0, choices: [], availableFor: [.kobraS1, .snapmakerU1], vendor: [.kobraS1: "10"]),
        SlicerOption(key: "wall_transition_filter_deviation", page: "Qualität", group: "Wandgenerator", kind: .percent, title: "Wandübergang: Filter", summary: "Verhindern Sie das Hin- und Herwechseln zwischen einer zusätzlichen Wand und einer weniger. Diese Spanne erweitert den Bereich der  Extrusionsbreiten auf [Mindestwandbreite - Spanne, 2 * Mindestwandbreite + Spanne]. Durch die Vergrößerung dieses Bereichs wird die Anzahl der Übergänge reduziert, was die Anzahl der Extrusionsstarts/-stopps und die Verfahrzeit verringert. Eine große Variation der Extrusionsbreite kann jedoch zu Unter- oder Überextrusionsproblemen führen. Er wird als Prozentsatz des Düsendurchmessers ausgedrückt", unit: "", min: 0.0, max: nil, choices: [], availableFor: [.kobraS1, .snapmakerU1], vendor: [.kobraS1: "25%"]),
        SlicerOption(key: "wall_transition_length", page: "Qualität", group: "Wandgenerator", kind: .percent, title: "Wandübergang: Länge", summary: "Beim Übergang zwischen verschiedenen Wandstärken, wenn das Teil dünner wird, wird eine bestimmte Menge an Platz zum Trennen oder Verbinden der Wandsegmente zugewiesen. Wird als Prozentsatz des Düsendurchmessers ausgedrückt.", unit: "", min: 0.0, max: nil, choices: [], availableFor: [.kobraS1, .snapmakerU1], vendor: [.kobraS1: "100%"]),
        SlicerOption(key: "wall_distribution_count", page: "Qualität", group: "Wandgenerator", kind: .int, title: "Wandverteilung: Anzahl", summary: "Die Anzahl der Wände, von der Mitte aus gezählt, über die die Veränderung verteilt werden muss. Niedrigere Werte bedeuten, dass sich die Außenwände nicht in der Breite verändern.", unit: "", min: 1.0, max: nil, choices: [], availableFor: [.kobraS1, .snapmakerU1], vendor: [.kobraS1: "1"]),
        SlicerOption(key: "initial_layer_min_bead_width", page: "Qualität", group: "Wandgenerator", kind: .percent, title: "Erste Schicht: minimale Linienbreite", summary: "Die minimale Wandbreite, die für die erste Schicht verwendet werden soll, sollte auf die gleiche Größe wie die Düse eingestellt werden. Diese Anpassung soll die Haftung verbessern.", unit: "", min: 0.0, max: nil, choices: [], availableFor: [.kobraS1, .snapmakerU1], vendor: [.kobraS1: "85%"]),
        SlicerOption(key: "min_bead_width", page: "Qualität", group: "Wandgenerator", kind: .percent, title: "Minimale Linienbreite", summary: "Breite der Wand, die dünne Features (entsprechend der Mindest-Featuregröße) des Modells ersetzen wird. Wenn die minimale Wandbreite dünner ist als die Dicke des Features, wird die Wand so dick wie das Feature selbst. Wird als Prozentsatz des Düsendurchmessers angegeben.", unit: "", min: 0.0, max: nil, choices: [], availableFor: [.kobraS1, .snapmakerU1], vendor: [.kobraS1: "85%"]),
        SlicerOption(key: "min_feature_size", page: "Qualität", group: "Wandgenerator", kind: .percent, title: "Minimale Strukturgröße", summary: "Minimale Dicke von dünnen Merkmalen. Merkmale des Modells, die dünner als dieser Wert sind, werden nicht gedruckt, während Merkmale, die dicker als dieser Wert sind, auf die minimale Wandbreite verbreitert werden. Wird als Prozentsatz des Düsendurchmessers ausgedrückt.", unit: "", min: 0.0, max: nil, choices: [], availableFor: [.kobraS1, .snapmakerU1], vendor: [.kobraS1: "25%"]),
        SlicerOption(key: "min_length_factor", page: "Qualität", group: "Wandgenerator", kind: .float, title: "Mindestlänge der Wandsegmente", summary: "Passen Sie diesen Wert an, um zu verhindern, dass kurze, offene Wände gedruckt werden, was die Druckzeit erhöhen könnte. Höhere Werte entfernen mehr und längere Wände.\n\nHINWEIS: Die unteren und oberen Oberflächen werden von diesem Wert nicht beeinflusst, um visuelle Lücken an der Außenseite des Modells zu vermeiden. Passen Sie die \"One wall threshold\" in den erweiterten Einstellungen unten an, um die Empfindlichkeit dessen anzupassen, was als obere Oberfläche angesehen wird. \"One wall threshold\" ist nur sichtbar, wenn diese Einstellung über den Standardwert von 0,5 gesetzt ist oder wenn einzelne Wände für die Oberfläche aktiviert sind.", unit: "mm", min: 0.0, max: 25.0, choices: [], availableFor: [.kobraS1, .snapmakerU1], vendor: [.kobraS1: "0.5"]),
        SlicerOption(key: "wall_sequence", page: "Qualität", group: "Wände und Oberflächen", kind: .choice, title: "Reihenfolge der Wände", summary: "In welcher Reihenfolge Innen- und Außenwände gedruckt werden.\n\nInnen/Außen ergibt die besten Überhänge, weil die Außenwand an der Nachbarwand haften kann. Außen/Innen ist maßgenauer, kann aber Überhänge verschlechtern.", unit: "", min: nil, max: nil, choices: [("inner wall/outer wall", "Innen/Außen"), ("outer wall/inner wall", "Außen/Innen"), ("inner-outer-inner wall", "Innenwand/Außenwand/Innenwand")], availableFor: [.kobraS1, .snapmakerU1], vendor: [.kobraS1: "inner wall/outer wall"]),
        SlicerOption(key: "is_infill_first", page: "Qualität", group: "Wände und Oberflächen", kind: .bool, title: "Füllung zuerst drucken", summary: "Reihenfolge der Wand/Füllung. Wenn das Kontrollkästchen nicht aktiviert ist,werden die Wände zuerst gedruckt, was in den meisten Fällen am besten funktioniert.\n\nDas Drucken der Füllung zuerst kann bei extremen Überhängen helfen, da die Wände an die benachbarte Füllung haften. Die Füllung drückt jedoch leicht gegen die gedruckten Wände, an denen sie befestigt ist, was zu einer schlechteren Oberflächenqualität führt. Es kann auch dazu führen, dass die Füllung durch die äußeren Oberflächen des Teils scheint.", unit: "", min: nil, max: nil, choices: [], availableFor: [.kobraS1, .snapmakerU1], vendor: [.kobraS1: "0"]),
        SlicerOption(key: "wall_direction", page: "Qualität", group: "Wände und Oberflächen", kind: .choice, title: "Druckrichtung der Wände", summary: "Richtung, in der Wandschleifen von oben gesehen gedruckt werden. Standardmäßig gegen den Uhrzeigersinn. „Auto“ lässt den Slicer entscheiden.", unit: "", min: nil, max: nil, choices: [("auto", "Automatisch"), ("ccw", "Gegen den Uhrzeigersinn"), ("cw", "Im Uhrzeigersinn")], availableFor: [.kobraS1, .snapmakerU1], vendor: [.kobraS1: "auto"]),
        SlicerOption(key: "print_flow_ratio", page: "Qualität", group: "Wände und Oberflächen", kind: .float, title: "Fluss (Flow Ratio, global)", summary: "Das Material kann sich nach dem Wechsel zwischen geschmolzenem und kristallinem Zustand volumetrisch verändern. Mit dieser Einstellung werden alle Extrusionsströme dieses Filaments im G-Code proportional geändert. Der empfohlene Wertebereich liegt zwischen 0,95 und 1,05. Sie können diesen Wert anpassen, um eine schöne flache Oberfläche zu erhalten, wenn es eine leichte Über- oder Unterextrusion gibt.\n\nDas endgültige Objekt-Flussverhältnis ist das Produkt aus diesem Wert und dem Filament-Flussverhältnis.", unit: "", min: 0.01, max: 2.0, choices: [], availableFor: [.kobraS1, .snapmakerU1], vendor: [.kobraS1: "1"]),
        SlicerOption(key: "top_solid_infill_flow_ratio", page: "Qualität", group: "Wände und Oberflächen", kind: .float, title: "Fluss Deckfläche", summary: "Dieser Faktor beeinflusst die Menge des Materials für die obere feste Füllung. Sie können ihn leicht verringern, um eine glatte Oberfläche zu erhalten.\n\nDer tatsächliche obere Fluss wird berechnet, indem dieser Wert mit dem Filamentflussverhältnis und, falls festgelegt, dem Objektflussverhältnis multipliziert wird.", unit: "", min: 0.0, max: 2.0, choices: [], availableFor: [.kobraS1, .snapmakerU1], vendor: [.kobraS1: "1"]),
        SlicerOption(key: "bottom_solid_infill_flow_ratio", page: "Qualität", group: "Wände und Oberflächen", kind: .float, title: "Fluss Bodenfläche", summary: "Dieser Faktor beeinflusst die Menge des Materials für die untere feste Füllung.\n\nDer tatsächliche Fluss für die untere feste Füllung wird berechnet, indem dieser Wert mit dem Filamentflussverhältnis und, falls festgelegt, dem Objektflussverhältnis multipliziert wird.", unit: "", min: 0.0, max: 2.0, choices: [], availableFor: [.kobraS1, .snapmakerU1], vendor: [.kobraS1: "1"]),
        SlicerOption(key: "only_one_wall_top", page: "Qualität", group: "Wände und Oberflächen", kind: .bool, title: "Nur eine Wand auf Deckflächen", summary: "Verwenden Sie nur eine Wand auf der Oberfläche, um mehr Platz für das obere Füllungsmuster zu schaffen", unit: "", min: nil, max: nil, choices: [], availableFor: [.kobraS1, .snapmakerU1], vendor: [.kobraS1: "1", .snapmakerU1: "1"]),
        SlicerOption(key: "min_width_top_surface", page: "Qualität", group: "Wände und Oberflächen", kind: .floatOrPercent, title: "Mindestbreite für eine Wand (Deckfläche)", summary: "Wenn eine obere Oberfläche gedruckt werden muss und sie teilweise von einer anderen Schicht bedeckt ist, wird sie nicht als obere Schicht betrachtet, wenn ihre Breite unterhalb dieses Werts liegt. Dies kann nützlich sein, um das Auslösen von 'einem Umfang oben' zu verhindern, wenn Oberflächen nur von Umfängen bedeckt werden sollen. Dieser Wert kann in Millimetern oder als Prozentsatz der Extrusionsbreite des Umfangs angegeben werden.\nWarnung: Wenn aktiviert, können Artefakte entstehen, wenn Sie dünnere Merkmale auf der nächsten Schicht haben, z. B. Buchstaben. Setzen Sie diesen Wert auf 0, um diese Artefakte zu entfernen.", unit: "mm oder %", min: 0.0, max: nil, choices: [], availableFor: [.kobraS1, .snapmakerU1], vendor: [.kobraS1: "300%"]),
        SlicerOption(key: "only_one_wall_first_layer", page: "Qualität", group: "Wände und Oberflächen", kind: .bool, title: "Nur eine Wand in der ersten Schicht", summary: "Verwenden Sie nur eine Wand in der ersten Schicht, um dem Muster der unteren Füllung mehr Platz zu geben", unit: "", min: nil, max: nil, choices: [], availableFor: [.kobraS1, .snapmakerU1], vendor: [.kobraS1: "0"]),
        SlicerOption(key: "reduce_crossing_wall", page: "Qualität", group: "Wände und Oberflächen", kind: .bool, title: "Wände nicht überfahren", summary: "Fahrwege machen Umwege, um nicht über Wände zu fahren. Das verhindert Klumpen auf der Oberfläche, verlängert aber die Druckzeit etwas.", unit: "", min: nil, max: nil, choices: [], availableFor: [.kobraS1, .snapmakerU1], vendor: [.kobraS1: "0", .snapmakerU1: "0"]),
        SlicerOption(key: "max_travel_detour_distance", page: "Qualität", group: "Wände und Oberflächen", kind: .floatOrPercent, title: "Maximaler Umweg bei Leerfahrten", summary: "Maximale Umleitstrecke zur Vermeidung einer Wandüberquerung: Der Drucker fährt keinen Umweg, wenn die Umleitstrecke größer als dieser Wert ist. Die Umleitstrecke kann entweder als absoluter Wert oder als Prozentsatz (z. B. 50 %) eines direkten Fahrwegs angegeben werden. Ein Wert von 0 deaktiviert diese Funktion.", unit: "mm oder %", min: 0.0, max: nil, choices: [], availableFor: [.kobraS1, .snapmakerU1], vendor: [.kobraS1: "0", .snapmakerU1: "0"]),
        SlicerOption(key: "small_area_infill_flow_compensation", page: "Qualität", group: "Wände und Oberflächen", kind: .bool, title: "Fluss-Ausgleich für kleine Füllflächen (Beta)", summary: "Flusskompensation für kleine Füllbereiche aktivieren", unit: "", min: nil, max: nil, choices: [], availableFor: [.kobraS1, .snapmakerU1], vendor: [.kobraS1: "0"]),
        SlicerOption(key: "bridge_flow", page: "Qualität", group: "Brücken", kind: .float, title: "Brückenfluss", summary: "Verringern Sie diesen Wert leicht (zum Beispiel 0,9), um die Materialmenge für die Brücke zu reduzieren und das Durchhängen zu verbessern.\n\nDer tatsächliche Brückenfluss wird berechnet, indem dieser Wert mit dem Filamentflussverhältnis und, falls festgelegt, dem Objektflussverhältnis multipliziert wird.", unit: "", min: 0.0, max: 2.0, choices: [], availableFor: [.kobraS1, .snapmakerU1], vendor: [.kobraS1: "1", .snapmakerU1: "1"]),
        SlicerOption(key: "internal_bridge_flow", page: "Qualität", group: "Brücken", kind: .float, title: "Fluss innere Brücken", summary: "Dieser Wert bestimmt die Dicke der internen Brückenschicht. Dies ist die erste Schicht über der dünnen Füllung. Verringern Sie diesen Wert leicht (zum Beispiel 0,9), um die Oberflächenqualität über der dünnen Füllung zu verbessern.\n\nDer tatsächliche interne Brückenfluss wird berechnet, indem dieser Wert mit dem Brückenflussverhältnis, dem Filamentflussverhältnis und, falls festgelegt, dem Objektflussverhältnis multipliziert wird.", unit: "", min: 0.0, max: 2.0, choices: [], availableFor: [.kobraS1, .snapmakerU1], vendor: [.kobraS1: "1"]),
        SlicerOption(key: "bridge_density", page: "Qualität", group: "Brücken", kind: .percent, title: "Dichte äußere Brücken", summary: "Steuerung der Dichte (Abstand) der externen Brückenlinien. 100 % bedeutet solide Brücke. Standard ist 100 %.\n\nNiedrigere Dichte externe Brücken können die Zuverlässigkeit verbessern, da mehr Platz für die Luftzirkulation um die extrudierte Brücke vorhanden ist, was die Kühlgeschwindigkeit verbessert.", unit: "", min: 10.0, max: 100.0, choices: [], availableFor: [.kobraS1, .snapmakerU1], vendor: [.kobraS1: "100%"]),
        SlicerOption(key: "internal_bridge_density", page: "Qualität", group: "Brücken", kind: .percent, title: "Dichte innere Brücken", summary: "Steuerung der Dichte (Abstand) der internen Brückenlinien. 100 % bedeutet solide Brücke. Standard ist 100 %.\n\nNiedrigere Dichte interne Brücken können das Pillowing der oberen Oberfläche reduzieren und die Zuverlässigkeit interner Brücken verbessern, da mehr Platz für die Luftzirkulation um die extrudierte Brücke vorhanden ist, was die Kühlgeschwindigkeit verbessert.\n\nDiese Option funktioniert besonders gut in Kombination mit der Option für die zweite interne Brücke über Füllung, die die interne Brückenstruktur weiter verbessert, bevor die feste Füllung extrudiert wird.", unit: "", min: 10.0, max: 100.0, choices: [], availableFor: [.kobraS1, .snapmakerU1], vendor: [:]),
        SlicerOption(key: "thick_bridges", page: "Qualität", group: "Brücken", kind: .bool, title: "Dicke äußere Brücken", summary: "Wenn diese Option aktiviert ist, sind die Brücken zuverlässiger und können größere Entfernungen überbrücken, sehen aber möglicherweise schlechter aus. Wenn deaktiviert, sehen Brücken besser aus, sind aber nur für kürzere Entfernungen zuverlässig.", unit: "", min: nil, max: nil, choices: [], availableFor: [.kobraS1, .snapmakerU1], vendor: [.kobraS1: "0"]),
        SlicerOption(key: "thick_internal_bridges", page: "Qualität", group: "Brücken", kind: .bool, title: "Dicke innere Brücken", summary: "Wenn diese Option aktiviert ist, werden dicke interne Brücken verwendet. Es wird normalerweise empfohlen, diese Funktion zu aktivieren. Wenn Sie jedoch große Düsen verwenden, sollten Sie diese Funktion deaktivieren.", unit: "", min: nil, max: nil, choices: [], availableFor: [.kobraS1, .snapmakerU1], vendor: [.kobraS1: "0"]),
        SlicerOption(key: "enable_extra_bridge_layer", page: "Qualität", group: "Brücken", kind: .choice, title: "Zusätzliche Brückenschicht (Beta)", summary: "Diese Option aktiviert die Erzeugung einer zusätzlichen Brückenschicht über internen und/oder externen Brücken.\n\nZusätzliche Brückenschichten verbessern das Aussehen und die Zuverlässigkeit von Brücken, da das feste Infill besser unterstützt wird. Dies ist besonders nützlich bei schnellen Druckern, bei denen die Brücken- und Feststofffüllungs-geschwindigkeiten stark variieren. Die zusätzliche Brückenschicht führt zu einer Verringerung des Pillowing auf den oberen Oberflächen sowie zu einer Verringerung der Ablösung der externen Brückenschicht von ihren umgebenden Umfängen.\n\nEs wird im Allgemeinen empfohlen, dies zumindest auf 'Nur externe Brücke' zu setzen, es sei denn, es werden spezifische Probleme mit dem geschnittenen Modell gefunden.\n\nOptionen:\n1. Deaktiviert - erzeugt keine zweiten Brückenschichten. Dies ist der Standard und wird aus Kompatibilitätsgründen festgelegt.\n2. Nur externe Brücke - erzeugt zweite Brückenschichten nur für nach außen gerichtete Brücken. Bitte beachten Sie, dass kleine Brücken, die kürzer oder schmaler sind als die festgelegte Anzahl von Umfängen, übersprungen werden, da sie von einer zweiten Brückenschicht nicht profitieren würden. Wenn erzeugt, wird die zweite Brückenschicht parallel zur ersten Brückenschicht extrudiert, um die Brückenfestigkeit zu verstärken.\n3. Nur interne Brücke - erzeugt zweite Brückenschichten nur für interne Brücken über dünner Füllung. Bitte beachten Sie, dass die internen Brücken zur Anzahl der oberen Schalenlagen Ihres Modells zählen. Die zweite interne Brückenschicht wird so nahe wie möglich senkrecht zur ersten extrudiert. Wenn mehrere Regionen in derselben Insel mit unterschiedlichen Brückenwinkeln vorhanden sind, wird die letzte Region dieser Insel als Winkelreferenz ausgewählt.\n4. Auf alle anwenden - erzeugt zweite Brückenschichten für interne und nach außen gerichtete Brücken\n", unit: "", min: nil, max: nil, choices: [("disabled", "Nicht aktiviert"), ("external_bridge_only", "Nur externe Brücke"), ("internal_bridge_only", "Nur interne Brücke"), ("apply_to_all", "Auf alle anwenden")], availableFor: [.kobraS1, .snapmakerU1], vendor: [:]),
        SlicerOption(key: "dont_filter_internal_bridges", page: "Qualität", group: "Brücken", kind: .choice, title: "Kleine innere Brücken filtern", summary: "Hilft gegen „Pillowing“ (Einsinken) auf Oberseiten bei stark geneigten oder gewölbten Modellen. Standardmäßig werden kleine innere Brücken ausgefiltert und die Vollfüllung direkt über die Füllung gedruckt.", unit: "", min: nil, max: nil, choices: [("disabled", "Filter"), ("limited", "Begrenzte Filterung"), ("nofilter", "Keine Filterung")], availableFor: [.kobraS1, .snapmakerU1], vendor: [.kobraS1: "disabled"]),
        SlicerOption(key: "counterbore_hole_bridging", page: "Qualität", group: "Brücken", kind: .choice, title: "Brücken über Senkungen", summary: "Diese Option erstellt Brücken für Senkungen, die es ermöglichen, sie ohne Unterstützung zu drucken. Die verfügbaren Modi sind:\n1. Keine: Es wird keine Brücke erstellt.\n2. Teilweise überbrückt: Nur ein Teil des nicht unterstützten Bereichs wird überbrückt.\n3. Opferschicht: Es wird eine vollständige opfernde Brückenschicht erstellt.", unit: "", min: nil, max: nil, choices: [], availableFor: [.kobraS1, .snapmakerU1], vendor: [.kobraS1: "none"]),
        SlicerOption(key: "detect_overhang_wall", page: "Qualität", group: "Überhänge", kind: .bool, title: "Überhänge erkennen", summary: "Erkennt, wie weit eine Wand überhängt (relativ zur Linienbreite), und druckt sie dann langsamer. Bei 100 % Überhang wird die Brückengeschwindigkeit genutzt.", unit: "", min: nil, max: nil, choices: [], availableFor: [.kobraS1, .snapmakerU1], vendor: [.kobraS1: "1", .snapmakerU1: "1"]),
        SlicerOption(key: "make_overhang_printable", page: "Qualität", group: "Überhänge", kind: .bool, title: "Überhänge druckbar machen", summary: "Die Geometrie anpassen, um Überhänge ohne Stützmaterial zu drucken.", unit: "", min: nil, max: nil, choices: [], availableFor: [.kobraS1, .snapmakerU1], vendor: [.kobraS1: "0"]),
        SlicerOption(key: "make_overhang_printable_angle", page: "Qualität", group: "Überhänge", kind: .float, title: "Überhänge druckbar: maximaler Winkel", summary: "Maximaler Winkel der Überhänge, die erlaubt sind, nachdem steilere Überhänge druckbar gemacht wurden. 90° wird das Modell überhaupt nicht verändern und jeden Überhang erlauben, während 0 alle Überhänge durch konisches Material ersetzt.", unit: "", min: 0.0, max: 90.0, choices: [], availableFor: [.kobraS1, .snapmakerU1], vendor: [.kobraS1: "55"]),
        SlicerOption(key: "make_overhang_printable_hole_size", page: "Qualität", group: "Überhänge", kind: .float, title: "Überhänge druckbar: maximale Lochgröße", summary: "Maximaler Flächenbereich eines Lochs in der Basis des Modells, bevor es mit konischem Material gefüllt wird. Ein Wert von 0 füllt alle Löcher in der Basis des Modells.", unit: "", min: 0.0, max: nil, choices: [], availableFor: [.kobraS1, .snapmakerU1], vendor: [.kobraS1: "0"]),
        SlicerOption(key: "extra_perimeters_on_overhangs", page: "Qualität", group: "Überhänge", kind: .bool, title: "Zusätzliche Wände bei Überhängen", summary: "Erstellen Sie zusätzliche Umfangspfade über steile Überhänge und Bereiche, in denen Brücken nicht verankert werden können.", unit: "", min: nil, max: nil, choices: [], availableFor: [.kobraS1, .snapmakerU1], vendor: [.kobraS1: "1"]),
        SlicerOption(key: "overhang_reverse", page: "Qualität", group: "Überhänge", kind: .bool, title: "Druckrichtung auf geraden Schichten umkehren", summary: "Extrudieren Sie Umfänge, die über einem Überhang liegen, in umgekehrter Richtung auf geraden Schichten. Dieses abwechselnde Muster kann steile Überhänge drastisch verbessern.\n\nDiese Einstellung kann auch dazu beitragen, das Verziehen des Teils aufgrund der Reduzierung der Spannungen in den Teilwänden zu verringern.", unit: "", min: nil, max: nil, choices: [], availableFor: [.kobraS1, .snapmakerU1], vendor: [.kobraS1: "0"]),
        SlicerOption(key: "overhang_reverse_internal_only", page: "Qualität", group: "Überhänge", kind: .bool, title: "Nur innere Wände umkehren", summary: "Wenden Sie die Logik der umgekehrten Umfänge nur auf interne Umfänge an.\n\nDiese Einstellung reduziert die Spannungen im Teil erheblich, da sie jetzt in abwechselnde Richtungen verteilt sind. Dies sollte das Verziehen des Teils reduzieren und gleichzeitig die Qualität der äußeren Wand erhalten. Diese Funktion kann sehr nützlich für Materialien sein, die zum Verziehen neigen, wie ABS/ASA, und auch für elastische Filamente, wie TPU und Seiden-PLA. Sie kann auch dazu beitragen, das Verziehen in schwebenden Bereichen über Stützen zu reduzieren.\n\nDamit diese Einstellung am effektivsten ist, wird empfohlen, den Umkehrschwellenwert auf 0 zu setzen, damit alle internen Wände auf geraden Schichten unabhängig von ihrem Überhangswinkel in abwechselnden Richtungen gedruckt werden.", unit: "", min: nil, max: nil, choices: [], availableFor: [.kobraS1, .snapmakerU1], vendor: [.kobraS1: "0"]),
        SlicerOption(key: "overhang_reverse_threshold", page: "Qualität", group: "Überhänge", kind: .floatOrPercent, title: "Umkehr-Schwelle (Überhang)", summary: "Die Anzahl der Millimeter, die der Überhang betragen muss, damit die Umkehrung als nützlich angesehen wird. Kann ein Prozentsatz der Umfangsbreite sein.\nDer Wert 0 aktiviert die Umkehrung auf jeder geraden Schicht unabhängig davon.\nWenn die Erkennung der Überhangswand nicht aktiviert ist, wird diese Option ignoriert und die Umkehrung erfolgt auf jeder geraden Schicht unabhängig davon.", unit: "mm oder %", min: 0.0, max: nil, choices: [], availableFor: [.kobraS1, .snapmakerU1], vendor: [.kobraS1: "50%"]),
        SlicerOption(key: "wall_loops", page: "Festigkeit", group: "Wände", kind: .int, title: "Anzahl der Wände (Perimeter)", summary: "Anzahl der Wände jeder Schicht", unit: "", min: 0.0, max: 1000.0, choices: [], availableFor: [.kobraS1, .snapmakerU1], vendor: [.kobraS1: "2", .snapmakerU1: "2"]),
        SlicerOption(key: "alternate_extra_wall", page: "Festigkeit", group: "Wände", kind: .bool, title: "Zusätzliche Wand im Wechsel", summary: "Diese Einstellung fügt jeder zweiten Schicht eine zusätzliche Wand hinzu. Damit wird die Füllung vertikal zwischen den Wänden eingeklemmt, was zu stärkeren Drucken führt.\n\nWenn diese Option aktiviert ist, muss die Option zur Sicherstellung der vertikalen Schalendicke deaktiviert werden.\n\nDie Verwendung von Lightning Infill zusammen mit dieser Option wird nicht empfohlen, da die Füllung begrenzt ist, um die zusätzlichen Umfänge zu verankern.", unit: "", min: nil, max: nil, choices: [], availableFor: [.kobraS1, .snapmakerU1], vendor: [.kobraS1: "0"]),
        SlicerOption(key: "detect_thin_wall", page: "Festigkeit", group: "Wände", kind: .bool, title: "Dünne Wände erkennen", summary: "Erkennt Wände, in die keine zwei Linien passen, und druckt sie mit einer einzelnen Linie. Das Ergebnis kann weniger sauber sein, weil keine geschlossene Schleife entsteht.", unit: "", min: nil, max: nil, choices: [], availableFor: [.kobraS1, .snapmakerU1], vendor: [.kobraS1: "0", .snapmakerU1: "0"]),
        SlicerOption(key: "top_shell_layers", page: "Festigkeit", group: "Obere/Untere Schichten", kind: .int, title: "Deckschichten", summary: "Dies ist die Anzahl der massiven Schichten der oberen Schale, einschließlich der Oberflächenschicht. Wenn die mit diesem Wert berechnete Dicke dünner ist als die Dicke der oberen Schale, werden die Schichten der oberen Schale erhöht.", unit: "Schichten", min: 0.0, max: nil, choices: [], availableFor: [.kobraS1, .snapmakerU1], vendor: [.kobraS1: "5", .snapmakerU1: "5"]),
        SlicerOption(key: "top_shell_thickness", page: "Festigkeit", group: "Obere/Untere Schichten", kind: .float, title: "Deckschichten: Mindestdicke", summary: "Die Anzahl der oberen festen Schichten wird beim Slicen erhöht, wenn die obere Schalenstärke dünner als dieser Wert ist. Dies kann verhindern, dass die Schale zu dünn wird, wenn eine geringe Schichthöhe verwendet wird. 0 bedeutet, dass diese Einstellung deaktiviert ist und die Dicke der oberen Schale absolut durch die oberen Schalenschichten bestimmt wird.", unit: "mm", min: 0.0, max: nil, choices: [], availableFor: [.kobraS1, .snapmakerU1], vendor: [.kobraS1: "1", .snapmakerU1: "1.0"]),
        SlicerOption(key: "top_surface_pattern", page: "Festigkeit", group: "Obere/Untere Schichten", kind: .choice, title: "Deckflächen-Muster", summary: "Füllmuster der obersten Fläche", unit: "", min: nil, max: nil, choices: [("monotonic", "Monotonisch"), ("monotonicline", "Monotonische Linie"), ("rectilinear", "Geradlinig"), ("alignedrectilinear", "Geradlinig ausgerichtet"), ("concentric", "Konzentrisch"), ("hilbertcurve", "Hilbert-Kurve"), ("archimedeanchords", "Archimedische Akkorde"), ("octagramspiral", "Oktagramm Spirale")], availableFor: [.kobraS1, .snapmakerU1], vendor: [.kobraS1: "monotonicline", .snapmakerU1: "monotonicline"]),
        SlicerOption(key: "bottom_shell_layers", page: "Festigkeit", group: "Obere/Untere Schichten", kind: .int, title: "Bodenschichten", summary: "Dies ist die Anzahl der massiven Schichten der Unterschale, einschließlich der ersten Schicht. Wenn die mit diesem Wert berechnete Dicke dünner ist als die Dicke der unteren Schale, werden die unteren Schalenschichten erhöht.", unit: "Schichten", min: 0.0, max: nil, choices: [], availableFor: [.kobraS1, .snapmakerU1], vendor: [.kobraS1: "3", .snapmakerU1: "3"]),
        SlicerOption(key: "bottom_shell_thickness", page: "Festigkeit", group: "Obere/Untere Schichten", kind: .float, title: "Bodenschichten: Mindestdicke", summary: "Die Anzahl der unteren festen Schichten wird beim Slicen erhöht, wenn die untere Schalenstärke dünner als dieser Wert ist. Dies kann verhindern, dass die Schale zu dünn wird, wenn eine geringe Schichthöhe verwendet wird. 0 bedeutet, dass diese Einstellung deaktiviert ist und die Dicke der unteren Schale absolut durch die unteren Schalenschichten bestimmt wird.", unit: "mm", min: 0.0, max: nil, choices: [], availableFor: [.kobraS1, .snapmakerU1], vendor: [.kobraS1: "0", .snapmakerU1: "0"]),
        SlicerOption(key: "bottom_surface_pattern", page: "Festigkeit", group: "Obere/Untere Schichten", kind: .choice, title: "Bodenflächen-Muster", summary: "Linienmuster der Bodenfüllung. Brückenfüllung nicht eingeschlossen", unit: "", min: nil, max: nil, choices: [], availableFor: [.kobraS1, .snapmakerU1], vendor: [.kobraS1: "monotonic", .snapmakerU1: "monotonic"]),
        SlicerOption(key: "top_bottom_infill_wall_overlap", page: "Festigkeit", group: "Obere/Untere Schichten", kind: .percent, title: "Überlappung Deck-/Bodenfüllung und Wand", summary: "Der obere massive Füllbereich wird leicht vergrößert, um mit der Wand zu überlappen und eine bessere Haftung zu gewährleisten und das Auftreten von Pinholes zu minimieren, wo die obere Füllung auf die Wände trifft. Ein Wert von 25-30% ist ein guter Ausgangspunkt, um das Auftreten von Pinholes zu minimieren. Der Prozentwert bezieht sich auf die Linienbreite der spärlichen Füllung.", unit: "", min: nil, max: nil, choices: [], availableFor: [.kobraS1, .snapmakerU1], vendor: [.kobraS1: "15%"]),
        SlicerOption(key: "sparse_infill_density", page: "Festigkeit", group: "Füllung", kind: .percent, title: "Fülldichte (Infill)", summary: "Dichte der internen Füllung, 100% verwandelt alle interne Füllung in massive Füllung und das interne massive Füllmuster wird verwendet.", unit: "", min: 0.0, max: 100.0, choices: [], availableFor: [.kobraS1, .snapmakerU1], vendor: [.kobraS1: "15%", .snapmakerU1: "15%"]),
        SlicerOption(key: "sparse_infill_pattern", page: "Festigkeit", group: "Füllung", kind: .choice, title: "Füllmuster (Infill)", summary: "Linienmuster für innere Füllung.", unit: "", min: nil, max: nil, choices: [("rectilinear", "Geradlinig"), ("alignedrectilinear", "Geradlinig ausgerichtet"), ("zigzag", "Zick-Zack"), ("crosszag", "Kreuz-Zag"), ("lockedzag", "Gesperrtes Zag"), ("line", "Linie"), ("grid", "Gitternetz"), ("triangles", "Dreiecke"), ("tri-hexagon", "Tri-Hexagon"), ("cubic", "Kubisch"), ("adaptivecubic", "Adaptiv kubisch"), ("quartercubic", "Viertel kubisch"), ("supportcubic", "Kubisch Stützen"), ("lightning", "Blitz"), ("honeycomb", "Bienenwabe"), ("3dhoneycomb", "3D-Waben"), ("lateral-honeycomb", "2D-Waben"), ("lateral-lattice", "2D-Gitter"), ("crosshatch", "Kreuzschraffur"), ("tpmsd", "TPMS-D"), ("tpmsfk", "TPMS-FK"), ("gyroid", "Gyroid"), ("concentric", "Konzentrisch"), ("hilbertcurve", "Hilbert-Kurve"), ("archimedeanchords", "Archimedische Akkorde"), ("octagramspiral", "Oktagramm Spirale")], availableFor: [.kobraS1, .snapmakerU1], vendor: [.kobraS1: "grid", .snapmakerU1: "crosshatch"]),
        SlicerOption(key: "infill_anchor_max", page: "Festigkeit", group: "Füllung", kind: .floatOrPercent, title: "Füllungsanker: maximale Länge", summary: "Verbindet Füllungslinien über ein kurzes Wandstück mit der Innenwand. Als Prozentwert bezieht sich die Länge auf die Füllungs-Linienbreite. Kürzer = weniger Material, länger = festere Anbindung.", unit: "", min: nil, max: nil, choices: [], availableFor: [.kobraS1, .snapmakerU1], vendor: [.kobraS1: "20"]),
        SlicerOption(key: "infill_anchor", page: "Festigkeit", group: "Füllung", kind: .floatOrPercent, title: "Füllungsanker: Länge", summary: "Verbindet Füllungslinien über ein kurzes Wandstück mit der Innenwand. Als Prozentwert bezieht sich die Länge auf die Füllungs-Linienbreite. 0 schaltet die Verankerung aus.", unit: "mm oder %", min: nil, max: nil, choices: [], availableFor: [.kobraS1, .snapmakerU1], vendor: [.kobraS1: "400%"]),
        SlicerOption(key: "internal_solid_infill_pattern", page: "Festigkeit", group: "Füllung", kind: .choice, title: "Muster der inneren Vollfüllung", summary: "Linienmuster des internen festen Füllmusters. Wenn die Erkennung von schmalem internen festen Infill aktiviert ist, wird das konzentrische Muster für den kleinen Bereich verwendet.", unit: "", min: nil, max: nil, choices: [], availableFor: [.kobraS1, .snapmakerU1], vendor: [.kobraS1: "zig-zag"]),
        SlicerOption(key: "gap_fill_target", page: "Festigkeit", group: "Füllung", kind: .choice, title: "Lückenfüllung: Ziel", summary: "Schaltet die Lückenfüllung für die ausgewählten massiven Oberflächen ein. Die minimale Lückenlänge, die gefüllt wird, kann von der Option zum Filtern kleiner Lücken unten gesteuert werden.\n\nOptionen:\n1. Überall: Füllt Lücken in oberen, unteren und internen massiven Oberflächen für maximale Festigkeit2. Obere und untere Oberflächen: Füllt Lücken nur in oberen und unteren Oberflächen, um Druckgeschwindigkeit zu erhöhen, potenzielle Überextrusion im massiven Infill zu reduzieren und sicherzustellen, dass die oberen und unteren Oberflächen keine Löcher aufweisen3. Nirgendwo: Deaktiviert die Lückenfüllung für alle massiven Infill-Bereiche.\n\nBeachten Sie, dass bei Verwendung des klassischen Umfangsgenerators Lückenfüllung auch zwischen Umfängen generiert werden kann, wenn eine volle Breitenlinie nicht zwischen ihnen passt. Diese Umfangslückenfüllung wird nicht durch diese Einstellung gesteuert.\n\nWenn Sie möchten, dass alle Lückenfüllungen, einschließlich der vom klassischen Umfangsgenerator generierten, entfernt werden, setzen Sie den Wert zum Filtern kleiner Lücken auf eine große Zahl, wie 999999.\n\nDies wird jedoch nicht empfohlen, da die Lückenfüllung zwischen Umfängen zur Festigkeit des Modells beiträgt. Für Modelle, bei denen zwischen Umfängen übermäßige Lückenfüllung generiert wird, wäre eine bessere Option, auf den Arachne-Wandgenerator umzusteigen und diese Option zu verwenden, um zu steuern, ob die kosmetische Lückenfüllung für obere und untere Oberflächen generiert wird.", unit: "", min: nil, max: nil, choices: [("everywhere", "Überall"), ("topbottom", "Obere und untere Oberflächen"), ("nowhere", "Nirgendwo")], availableFor: [.kobraS1, .snapmakerU1], vendor: [.kobraS1: "topbottom"]),
        SlicerOption(key: "filter_out_gap_fill", page: "Festigkeit", group: "Füllung", kind: .float, title: "Kleine Lücken nicht füllen", summary: "Drucken Sie keine Lückenfüllung mit einer Länge, die kleiner als der angegebene Schwellenwert (in mm) ist. Diese Einstellung gilt für die obere, untere und massive Füllung und, wenn der klassische Perimeter-Generator verwendet wird, für die Wandlückenfüllung.", unit: "mm", min: nil, max: nil, choices: [], availableFor: [.kobraS1, .snapmakerU1], vendor: [.kobraS1: "0"]),
        SlicerOption(key: "infill_wall_overlap", page: "Festigkeit", group: "Füllung", kind: .percent, title: "Überlappung Füllung/Wand", summary: "Die Füllfläche wird leicht vergrößert, um mit der Wand zu überlappen und eine bessere Haftung zu gewährleisten. Der Prozentwert bezieht sich auf die Linienbreite der spärlichen Füllung. Setzen Sie diesen Wert auf ~10-15%, um eine mögliche Überextrusion und Materialansammlung zu minimieren, die zu rauen Oberflächen führen kann.", unit: "", min: nil, max: nil, choices: [], availableFor: [.kobraS1, .snapmakerU1], vendor: [.kobraS1: "15%", .snapmakerU1: "15%"]),
        SlicerOption(key: "infill_direction", page: "Festigkeit", group: "Erweiterte Einstellungen", kind: .float, title: "Winkel der Füllung", summary: "Winkel des Füllmusters, das die Richtung der Linien bestimmt.", unit: "", min: 0.0, max: 360.0, choices: [], availableFor: [.kobraS1, .snapmakerU1], vendor: [.kobraS1: "45", .snapmakerU1: "45"]),
        SlicerOption(key: "solid_infill_direction", page: "Festigkeit", group: "Erweiterte Einstellungen", kind: .float, title: "Winkel der Vollfüllung", summary: "Winkel des massiven Füllmusters, der die Start- oder Hauptrichtung der Linie steuert.", unit: "", min: 0.0, max: 360.0, choices: [], availableFor: [.kobraS1, .snapmakerU1], vendor: [.kobraS1: "45"]),
        SlicerOption(key: "rotate_solid_infill_direction", page: "Festigkeit", group: "Erweiterte Einstellungen", kind: .bool, title: "Vollfüllung je Schicht um 90° drehen", summary: "Dreht die Richtung der Vollfüllung in jeder Schicht um 90°. Ergibt dichtere, gleichmäßigere Deckflächen.", unit: "", min: nil, max: nil, choices: [], availableFor: [.kobraS1], vendor: [.kobraS1: "1"]),
        SlicerOption(key: "bridge_angle", page: "Festigkeit", group: "Erweiterte Einstellungen", kind: .float, title: "Winkel äußerer Brücken", summary: "Überbrückungswinkel überschreiben. 0 bedeutet, dass der Überbrückungswinkel automatisch berechnet wird. Andernfalls wird der angegebene Winkel für externe Brücken verwendet. Verwenden Sie 180° für keinen Winkel.", unit: "", min: 0.0, max: nil, choices: [], availableFor: [.kobraS1, .snapmakerU1], vendor: [.kobraS1: "0"]),
        SlicerOption(key: "internal_bridge_angle", page: "Festigkeit", group: "Erweiterte Einstellungen", kind: .float, title: "Winkel innerer Brücken", summary: "Überschreibt den Winkel für innere Brücken. Bei 0 berechnet der Slicer ihn automatisch (empfohlen). Bei Bedarf 180° für „0 Grad“ eingeben.", unit: "", min: 0.0, max: nil, choices: [], availableFor: [.kobraS1, .snapmakerU1], vendor: [:]),
        SlicerOption(key: "minimum_sparse_infill_area", page: "Festigkeit", group: "Erweiterte Einstellungen", kind: .float, title: "Mindestfläche der Füllung", summary: "Füllungsflächen, die kleiner als dieser Wert sind, werden durch Vollfüllung ersetzt. Vermeidet winzige, wenig sinnvolle Füllungsinseln.", unit: "", min: 0.0, max: nil, choices: [], availableFor: [.kobraS1, .snapmakerU1], vendor: [.kobraS1: "15", .snapmakerU1: "15"]),
        SlicerOption(key: "infill_combination", page: "Festigkeit", group: "Erweiterte Einstellungen", kind: .bool, title: "Füllung über mehrere Schichten kombinieren", summary: "Kombinieren Sie automatisch die Füllung von mehreren Schichten, um diese gemeinsam zu drucken und Zeit zu sparen. Die Wand wird weiterhin mit der ursprünglichen Schichthöhe gedruckt.", unit: "", min: nil, max: nil, choices: [], availableFor: [.kobraS1, .snapmakerU1], vendor: [.kobraS1: "0", .snapmakerU1: "0"]),
        SlicerOption(key: "infill_combination_max_layer_height", page: "Festigkeit", group: "Erweiterte Einstellungen", kind: .floatOrPercent, title: "Kombinierte Füllung: maximale Schichthöhe", summary: "Maximale Schichthöhe für die kombinierte spärliche Füllung.\n\nSetzen Sie sie auf 0 oder 100%, um den Düsendurchmesser zu verwenden (für eine maximale Reduzierung der Druckzeit) oder einen Wert von ~80%, um die Festigkeit der spärlichen Füllung zu maximieren.\n\nDie Anzahl der Schichten, über die die Füllung kombiniert wird, wird durch Division dieses Werts durch die Schichthöhe abgeleitet und auf die nächste Dezimalstelle abgerundet.\n\nVerwenden Sie entweder absolute mm-Werte (z. B. 0,32 mm für eine 0,4 mm Düse) oder % Werte (z. B. 80%). Dieser Wert darf nicht größer als der Düsendurchmesser sein.", unit: "mm oder %", min: 0.0, max: nil, choices: [], availableFor: [.kobraS1, .snapmakerU1], vendor: [.kobraS1: "100%"]),
        SlicerOption(key: "detect_narrow_internal_solid_infill", page: "Festigkeit", group: "Erweiterte Einstellungen", kind: .bool, title: "Schmale innere Vollfüllung erkennen", summary: "Erkennt schmale innere Vollfüllungsflächen und druckt sie konzentrisch statt geradlinig. Das beschleunigt den Druck.", unit: "", min: nil, max: nil, choices: [], availableFor: [.kobraS1, .snapmakerU1], vendor: [.kobraS1: "1"]),
        SlicerOption(key: "ensure_vertical_shell_thickness", page: "Festigkeit", group: "Erweiterte Einstellungen", kind: .choice, title: "Dicke senkrechter Wände sicherstellen", summary: "Fügen Sie massives Infill in der Nähe von geneigten Oberflächen hinzu, um die vertikale Wanddicke (obere + untere feste Schichten) zu garantieren\nKeine: Kein massives Infill wird irgendwo hinzugefügt. Vorsicht: Verwenden Sie diese Option vorsichtig, wenn Ihr Modell geneigte Oberflächen hat\nNur kritisch: Vermeiden Sie das Hinzufügen von massivem Infill für Wände\nModerat: Fügen Sie massives Infill nur für stark geneigte Oberflächen hinzu\nAlle: Fügen Sie massives Infill für alle geeigneten geneigten Oberflächen hinzu\nDer Standardwert ist Alle.", unit: "", min: nil, max: nil, choices: [("none", "Keine"), ("ensure_critical_only", "Nur kritisch"), ("ensure_moderate", "Moderat"), ("ensure_all", "Alle")], availableFor: [.kobraS1, .snapmakerU1], vendor: [.kobraS1: "ensure_all"]),
        SlicerOption(key: "initial_layer_speed", page: "Geschwindigkeit", group: "Geschwindigkeit der ersten Schicht", kind: .float, title: "Tempo erste Schicht", summary: "Geschwindigkeit der ersten Schicht ohne den Vollfüllungs-Anteil. Langsam = bessere Haftung.", unit: "mm/s", min: 1.0, max: nil, choices: [], availableFor: [.kobraS1, .snapmakerU1], vendor: [.kobraS1: "50", .snapmakerU1: "50"]),
        SlicerOption(key: "initial_layer_infill_speed", page: "Geschwindigkeit", group: "Geschwindigkeit der ersten Schicht", kind: .float, title: "Tempo erste Schicht (Füllung)", summary: "Geschwindigkeit des Vollfüllungs-Anteils der ersten Schicht.", unit: "mm/s", min: 1.0, max: nil, choices: [], availableFor: [.kobraS1, .snapmakerU1], vendor: [.kobraS1: "80", .snapmakerU1: "105"]),
        SlicerOption(key: "initial_layer_travel_speed", page: "Geschwindigkeit", group: "Geschwindigkeit der ersten Schicht", kind: .floatOrPercent, title: "Leerfahrt-Tempo erste Schicht", summary: "Fahrgeschwindigkeit ohne Extrusion in der ersten Schicht.", unit: "mm/s oder %", min: 1.0, max: nil, choices: [], availableFor: [.kobraS1, .snapmakerU1], vendor: [.kobraS1: "100%"]),
        SlicerOption(key: "slow_down_layers", page: "Geschwindigkeit", group: "Geschwindigkeit der ersten Schicht", kind: .int, title: "Anzahl langsamer Schichten am Anfang", summary: "Die ersten paar Schichten werden langsamer als normal gedruckt. Die Geschwindigkeitwird allmählich linear über die angegebene Anzahl von Schichten erhöht.", unit: "Schichten", min: 0.0, max: nil, choices: [], availableFor: [.kobraS1, .snapmakerU1], vendor: [.kobraS1: "0"]),
        SlicerOption(key: "outer_wall_speed", page: "Geschwindigkeit", group: "Geschwindigkeit der restlichen Schichten", kind: .float, title: "Tempo Außenwand", summary: "Geschwindigkeit der äußersten Wand, welche später sichtbar ist. Wird in der Regel langsamer als die Innenwände gedruckt, um eine bessere Qualität zu erzielen.", unit: "mm/s", min: 1.0, max: nil, choices: [], availableFor: [.kobraS1, .snapmakerU1], vendor: [.kobraS1: "200", .snapmakerU1: "200"]),
