        SlicerOption(key: "travel_jerk", page: "Geschwindigkeit", group: "Jerk(XY)", kind: .float, title: "Ruck Leerfahrt", summary: "Jerk for Bewegung", unit: "mm/s", min: 0.0, max: nil, choices: [], availableFor: [.kobraS1, .snapmakerU1], vendor: [.kobraS1: "9"]),
        SlicerOption(key: "max_volumetric_extrusion_rate_slope", page: "Geschwindigkeit", group: "Erweiterte Einstellungen", kind: .float, title: "Extrusionsrate glätten (Rate Smoothing)", summary: "Dieser Parameter gleicht plötzliche Änderungen der Extrusionsrate aus, die auftreten, wenn der Drucker von einer hohen Flussrate (hohe Geschwindigkeit/größere Breite) zu einer niedrigeren Flussrate (niedrigere Geschwindigkeit/kleinere Breite) und umgekehrt wechselt.\n\nEs definiert die maximale Rate, mit der sich der extrudierte Volumenstrom in mm³/s über die Zeit ändern kann. Höhere Werte bedeuten, dass höhere Extrusionsratenänderungen zulässig sind, was zu schnelleren Geschwindigkeitsübergängen führt.\n\nEin Wert von 0 deaktiviert die Funktion.\n\nFür einen Hochgeschwindigkeits-, Hochfluss-Direktantriebsdrucker (wie den Bambu-Labor- oder Voron-Drucker) ist dieser Wert normalerweise nicht erforderlich. Er kann jedoch in bestimmten Fällen einen geringfügigen Vorteil bieten, in denen sich die Funktionen stark unterscheiden. Zum Beispiel, wenn es aggressive Verlangsamungen aufgrund von Überhängen gibt. In diesen Fällen wird ein hoher Wert von ca. 300-350 mm³/s² empfohlen, da ", unit: "", min: 0.0, max: nil, choices: [], availableFor: [.kobraS1, .snapmakerU1], vendor: [.kobraS1: "0"]),
        SlicerOption(key: "max_volumetric_extrusion_rate_slope_segment_length", page: "Geschwindigkeit", group: "Erweiterte Einstellungen", kind: .float, title: "Extrusionsrate glätten: Segmentlänge", summary: "Ein niedrigerer Wert führt zu glatteren Extrusionsratenübergängen. Dies führt jedoch zu einer deutlich größeren G-Code-Datei und mehr Anweisungen für den Drucker, um zu verarbeiten.\n\nDer Standardwert von 3 funktioniert in den meisten Fällen gut. Wenn Ihr Drucker stottert, erhöhen Sie diesen Wert, um die Anzahl der Anpassungen zu reduzieren.\n\nZulässige Werte: 0,5-5", unit: "mm", min: 0.5, max: 5.0, choices: [], availableFor: [.kobraS1, .snapmakerU1], vendor: [.kobraS1: "3"]),
        SlicerOption(key: "extrusion_rate_smoothing_external_perimeter_only", page: "Geschwindigkeit", group: "Erweiterte Einstellungen", kind: .bool, title: "Glättung nur an der Außenwand", summary: "Wendet die Extrusionsraten-Glättung nur auf externe Umfänge und Überhänge an. Dies kann dazu beitragen, Artefakte aufgrund scharfer Geschwindigkeits-übergänge an extern sichtbaren Überhängen zu reduzieren, ohne die Druck-geschwindigkeit von Funktionen zu beeinträchtigen, die für den Benutzer nicht sichtbar sind.", unit: "", min: nil, max: nil, choices: [], availableFor: [.kobraS1, .snapmakerU1], vendor: [:]),
        SlicerOption(key: "enable_support", page: "Stützen", group: "Stützen", kind: .bool, title: "Stützstruktur (Support) einschalten", summary: "Erzeugung von Stützstrukturen aktivieren.", unit: "", min: nil, max: nil, choices: [], availableFor: [.kobraS1, .snapmakerU1], vendor: [.kobraS1: "0", .snapmakerU1: "0"]),
        SlicerOption(key: "support_type", page: "Stützen", group: "Stützen", kind: .choice, title: "Support-Typ", summary: "Normal (auto) und Tree (auto) werden verwendet, um Stützstrukturen automatisch zu generieren. Wenn Normal (manual) oder Tree (manual) ausgewählt wird, werden nur Stützverstärker generiert.", unit: "", min: nil, max: nil, choices: [("normal(auto)", "Normal (automatisch)"), ("tree(auto)", "Baum (automatisch)"), ("normal(manual)", "Normal (manuell)"), ("tree(manual)", "Baum (manuell)")], availableFor: [.kobraS1, .snapmakerU1], vendor: [.kobraS1: "tree(auto)", .snapmakerU1: "normal(auto)"]),
        SlicerOption(key: "support_style", page: "Stützen", group: "Stützen", kind: .choice, title: "Support-Stil", summary: "Stil und Form der Stützstrukturen. Für normale Stützstrukturen erzeugt die Projektion der Stützstrukturen in ein regelmäßiges Gitter stabilere Stützstrukturen (Standard), während schlanke Stütztürme Material sparen und Objektverletzungen reduzieren.\nFür Baumstützen werden die schlanken und organischen Stile die Äste aggressiver zusammenführen und viel Material sparen (Standardorganisch), während der Hybridstil eine ähnliche Struktur wie normale Stützstrukturen unter großen flachen Überhängen erzeugt.", unit: "", min: nil, max: nil, choices: [("default", "Standard (Gitter/Organisch)"), ("grid", "Gitternetz"), ("snug", "Nahtlos"), ("organic", "Organisch"), ("tree_slim", "Baum schlank"), ("tree_strong", "Baum stark"), ("tree_hybrid", "Baum-Hybrid")], availableFor: [.kobraS1, .snapmakerU1], vendor: [.kobraS1: "default", .snapmakerU1: "default"]),
        SlicerOption(key: "support_threshold_angle", page: "Stützen", group: "Stützen", kind: .int, title: "Support-Winkelschwelle", summary: "Für Überhänge, deren Neigungswinkel unter diesem Wert liegt, werden Stützen generiert.", unit: "", min: 0.0, max: 90.0, choices: [], availableFor: [.kobraS1, .snapmakerU1], vendor: [.kobraS1: "30", .snapmakerU1: "30"]),
        SlicerOption(key: "support_threshold_overlap", page: "Stützen", group: "Stützen", kind: .floatOrPercent, title: "Support-Überlappungsschwelle", summary: "Wenn der Schwellenwinkel null ist, werden Stützen für Überhänge generiert, deren Überlappung unter dem Schwellenwert liegt. Je kleiner dieser Wert ist, desto steiler kann der Überhang gedruckt werden, ohne Stützen zu benötigen.", unit: "mm oder %", min: 0.0, max: 100.0, choices: [], availableFor: [.kobraS1, .snapmakerU1], vendor: [:]),
        SlicerOption(key: "raft_first_layer_density", page: "Stützen", group: "Stützen", kind: .percent, title: "Raft: Dichte erste Schicht", summary: "Dichte der ersten Schicht der Druckbasis oder Support", unit: "", min: 10.0, max: 100.0, choices: [], availableFor: [.kobraS1, .snapmakerU1], vendor: [.kobraS1: "90%"]),
