        SlicerOption(key: "solid_infill_filament", page: "Mehrfarben", group: "Filament für Funktionen", kind: .int, title: "Filament für Vollfüllung", summary: "Welches Filament die Vollfüllung (Boden und Deckel) druckt.", unit: "", min: 1.0, max: nil, choices: [], availableFor: [.kobraS1, .snapmakerU1], vendor: [.kobraS1: "1"]),
        SlicerOption(key: "wipe_tower_filament", page: "Mehrfarben", group: "Filament für Funktionen", kind: .int, title: "Filament für Reinigungsturm", summary: "Der Extruder, der zum Drucken des Umfangs des Reinigungsturms verwendet wird. Auf 0 setzen, um den verfügbaren Extruder zu verwenden (nicht lösliches Filament wird bevorzugt).", unit: "", min: 0.0, max: nil, choices: [], availableFor: [.kobraS1, .snapmakerU1], vendor: [.kobraS1: "0", .snapmakerU1: "0"]),
        SlicerOption(key: "ooze_prevention", page: "Mehrfarben", group: "Ooze-Prävention", kind: .bool, title: "Nachsickern verhindern (Ooze Prevention)", summary: "Diese Option senkt die Temperatur der inaktiven Extruder, um das Herauslaufen des Filaments zu verhindern.", unit: "", min: nil, max: nil, choices: [], availableFor: [.kobraS1, .snapmakerU1], vendor: [.kobraS1: "0", .snapmakerU1: "1"]),
        SlicerOption(key: "standby_temperature_delta", page: "Mehrfarben", group: "Ooze-Prävention", kind: .int, title: "Standby-Temperaturabsenkung", summary: "Temperaturunterschied, der angewendet wird, wenn ein Extruder nicht aktiv ist. Der Wert wird nicht verwendet, wenn 'idle_temperature' in den Filament-Einstellungen auf einen Wert ungleich Null gesetzt ist.", unit: "", min: nil, max: nil, choices: [], availableFor: [.kobraS1, .snapmakerU1], vendor: [.kobraS1: "0", .snapmakerU1: "-150"]),
        SlicerOption(key: "preheat_time", page: "Mehrfarben", group: "Ooze-Prävention", kind: .float, title: "Vorheizzeit", summary: "Um die Wartezeit nach dem Werkzeugwechsel zu reduzieren, kann Orca das nächste Werkzeug vorheizen, während das aktuelle Werkzeug noch in Gebrauch ist. Diese Einstellung gibt die Zeit in Sekunden an, um das nächste Werkzeug vorzuheizen. Orca fügt einen M104-Befehl ein, um das Werkzeug im Voraus zu vorzuheizen.", unit: "", min: 0.0, max: 120.0, choices: [], availableFor: [.kobraS1, .snapmakerU1], vendor: [.kobraS1: "0", .snapmakerU1: "30"]),
        SlicerOption(key: "preheat_steps", page: "Mehrfarben", group: "Ooze-Prävention", kind: .int, title: "Vorheiz-Schritte", summary: "Fügen Sie mehrere Vorheizbefehle ein (z.B. M104.1). Nur nützlich für Prusa XL. Für andere Drucker bitte auf 1 setzen.", unit: "", min: 1.0, max: 10.0, choices: [], availableFor: [.kobraS1, .snapmakerU1], vendor: [.kobraS1: "1"]),
        SlicerOption(key: "flush_into_infill", page: "Mehrfarben", group: "Optionen für die Düsenreinigung", kind: .bool, title: "In Füllung spülen", summary: "Die Reinigung nach dem Filamentwechsel erfolgt innerhalb der Objektfüllung. Dies kann die Abfallmenge verringern und die Druckzeit verkürzen. Wenn die Wände mit transparentem Filament gedruckt werden, sind die unterschiedlichen Farben der Füllung sichtbar. Die Funktion ist nur dann wirksam, wenn der Reinigungsturm aktiviert ist.", unit: "", min: nil, max: nil, choices: [], availableFor: [.kobraS1, .snapmakerU1], vendor: [.kobraS1: "0"]),
        SlicerOption(key: "flush_into_objects", page: "Mehrfarben", group: "Optionen für die Düsenreinigung", kind: .bool, title: "In Objekt spülen", summary: "Dieses Objekt wird verwendet, um die Düse nach einem Filamentwechsel zu reinigen, Filament zu sparen und die Druckzeit zu verkürzen. Die Farben der Objekte werden dadurch gemischt. Dies wird nur wirksam, wenn der Reinigungsturm aktiviert ist.", unit: "", min: nil, max: nil, choices: [], availableFor: [.kobraS1, .snapmakerU1], vendor: [.kobraS1: "0"]),
        SlicerOption(key: "flush_into_support", page: "Mehrfarben", group: "Optionen für die Düsenreinigung", kind: .bool, title: "In Support spülen", summary: "Die Reinigung nach dem Filamentwechsel erfolgt innerhalb der Stützstrukturen. Dies kann die Abfallmenge verringern und die Druckzeit verkürzen. Die Funktion ist nur dann wirksam, wenn der Reinigungsturm aktiviert ist.", unit: "", min: nil, max: nil, choices: [], availableFor: [.kobraS1, .snapmakerU1], vendor: [.kobraS1: "1"]),
        SlicerOption(key: "interlocking_beam", page: "Mehrfarben", group: "Erweiterte Einstellungen", kind: .bool, title: "Verzahnte Strukturen (Interlocking)", summary: "Erzeugen Sie eine verzahnte Struktur an den Stellen, an denen sich unterschiedliche Filamente berühren. Dies verbessert die Haftung zwischen den Filamenten, insbesondere bei Modellen, die aus verschiedenen Materialien gedruckt werden.", unit: "", min: nil, max: nil, choices: [], availableFor: [.kobraS1, .snapmakerU1], vendor: [.kobraS1: "0"]),
        SlicerOption(key: "interface_shells", page: "Mehrfarben", group: "Erweiterte Einstellungen", kind: .bool, title: "Schalen zwischen Materialien", summary: "Erzwingen der Erstellung von festen Hüllen zwischen benachbarten Materialien/Volumina“ ist eine Funktion, die bei Drucken mit mehreren Extrudern verwendet werden kann, insbesondere bei Drucken mit durchsichtigen Materialien oder manuell lösbaren Unterstützungsmaterialien", unit: "", min: nil, max: nil, choices: [], availableFor: [.kobraS1, .snapmakerU1], vendor: [.kobraS1: "0", .snapmakerU1: "0"]),
        SlicerOption(key: "mmu_segmented_region_max_width", page: "Mehrfarben", group: "Erweiterte Einstellungen", kind: .float, title: "Max. Breite segmentierter Bereiche", summary: "Maximale Breite eines segmentierten Bereichs. Null deaktiviert diese Funktion.", unit: "mm", min: 0.0, max: nil, choices: [], availableFor: [.kobraS1, .snapmakerU1], vendor: [.kobraS1: "0"]),
        SlicerOption(key: "mmu_segmented_region_interlocking_depth", page: "Mehrfarben", group: "Erweiterte Einstellungen", kind: .float, title: "Verzahnungstiefe segmentierter Bereiche", summary: "Interlock-Tiefe eines segmentierten Bereichs. Es wird ignoriert, wenn \"mmu_segmented_region_max_width\" null ist oder wenn \"mmu_segmented_region_interlocking_depth\" größer ist als \"mmu_segmented_region_max_width\". Null deaktiviert diese Funktion.", unit: "", min: 0.0, max: nil, choices: [], availableFor: [.kobraS1, .snapmakerU1], vendor: [.kobraS1: "0"]),
        SlicerOption(key: "interlocking_beam_width", page: "Mehrfarben", group: "Erweiterte Einstellungen", kind: .float, title: "Verzahnung: Balkenbreite", summary: "Die Breite der Interlock-Strukturen.", unit: "mm", min: 0.01, max: nil, choices: [], availableFor: [.kobraS1, .snapmakerU1], vendor: [.kobraS1: "0.8"]),
        SlicerOption(key: "interlocking_orientation", page: "Mehrfarben", group: "Erweiterte Einstellungen", kind: .float, title: "Verzahnung: Ausrichtung", summary: "Ausrichtung der Interlock-Strukturen.", unit: "", min: 0.0, max: 360.0, choices: [], availableFor: [.kobraS1, .snapmakerU1], vendor: [.kobraS1: "22.5"]),
        SlicerOption(key: "interlocking_beam_layer_count", page: "Mehrfarben", group: "Erweiterte Einstellungen", kind: .int, title: "Verzahnung: Schichten je Balken", summary: "Die Höhe der Balken der Interlock-Strukture, gemessen in Anzahl von Schichten. Weniger Schichten sind stärker, aber anfälliger für Fehler.", unit: "", min: 1.0, max: nil, choices: [], availableFor: [.kobraS1, .snapmakerU1], vendor: [.kobraS1: "2"]),
        SlicerOption(key: "interlocking_depth", page: "Mehrfarben", group: "Erweiterte Einstellungen", kind: .int, title: "Verzahnung: Tiefe", summary: "Der Abstand von der Grenze zwischen den Filamenten, um die Interlock-Strukturen-zu generieren, gemessen in Zellen. Zu wenige Zellen führen zu einer schlechten Haftung.", unit: "", min: 1.0, max: nil, choices: [], availableFor: [.kobraS1, .snapmakerU1], vendor: [.kobraS1: "2"]),
        SlicerOption(key: "interlocking_boundary_avoidance", page: "Mehrfarben", group: "Erweiterte Einstellungen", kind: .int, title: "Verzahnung: Abstand zur Grenze", summary: "Der Abstand von der Außenseite eines Modells, an dem keine Interlock-Strukturen generiert werden, gemessen in Zellen.", unit: "", min: 0.0, max: nil, choices: [], availableFor: [.kobraS1, .snapmakerU1], vendor: [.kobraS1: "2"]),
        SlicerOption(key: "skirt_loops", page: "Sonstiges", group: "Saum", kind: .int, title: "Schürze (Skirt): Anzahl Linien", summary: "Anzahl der Ringe für die Umrandung. Null bedeutet Deaktivierung der Umrandung", unit: "", min: 0.0, max: 10.0, choices: [], availableFor: [.kobraS1, .snapmakerU1], vendor: [.kobraS1: "0", .snapmakerU1: "0"]),
        SlicerOption(key: "skirt_type", page: "Sonstiges", group: "Saum", kind: .choice, title: "Schürze: Art", summary: "Kombiniert - eine Umrandung für alle Objekte, Pro Objekt - individuelle Objektumrandung.", unit: "", min: nil, max: nil, choices: [("combined", "Kombiniert"), ("perobject", "Pro Objekt")], availableFor: [.kobraS1, .snapmakerU1], vendor: [.kobraS1: "combined"]),
        SlicerOption(key: "min_skirt_length", page: "Sonstiges", group: "Saum", kind: .float, title: "Schürze: Mindest-Filamentlänge", summary: "Minimale Filamentextrusionslänge in mm beim Drucken der Umrandung. Null bedeutet, dass diese Funktion deaktiviert ist.\n\nDie Verwendung eines Werts ungleich Null ist nützlich, wenn der Drucker so eingestellt ist, dass er ohne eine Primelinie druckt.\nDie endgültige Anzahl der Schleifen wird nicht berücksichtigt, wenn die Objektabstände angeordnet oder validiert werden. Erhöhen Sie die Anzahl der Schleifen in einem solchen Fall.", unit: "mm", min: 0.0, max: nil, choices: [], availableFor: [.kobraS1, .snapmakerU1], vendor: [.kobraS1: "0"]),
        SlicerOption(key: "skirt_distance", page: "Sonstiges", group: "Saum", kind: .float, title: "Schürze: Abstand zum Teil", summary: "Abstand von der Umrandung zum Rand oder zum Objekt", unit: "mm", min: 0.0, max: 60.0, choices: [], availableFor: [.kobraS1, .snapmakerU1], vendor: [.kobraS1: "2", .snapmakerU1: "2"]),
        SlicerOption(key: "skirt_start_angle", page: "Sonstiges", group: "Saum", kind: .float, title: "Schürze: Startwinkel", summary: "Winkel vom Objektzentrum zum Startpunkt der Umrandung. Null ist die rechteste Position, gegen den Uhrzeigersinn ist der Winkel positiv.", unit: "", min: -180.0, max: 180.0, choices: [], availableFor: [.kobraS1, .snapmakerU1], vendor: [.kobraS1: "-135"]),
        SlicerOption(key: "skirt_height", page: "Sonstiges", group: "Saum", kind: .int, title: "Schürze: Höhe in Schichten", summary: "Wie viele Schichten des Skirts. Normalerweise nur eine Schicht.", unit: "Schichten", min: nil, max: 10000.0, choices: [], availableFor: [.kobraS1, .snapmakerU1], vendor: [.kobraS1: "1", .snapmakerU1: "1"]),
        SlicerOption(key: "skirt_speed", page: "Sonstiges", group: "Saum", kind: .float, title: "Schürze: Tempo", summary: "Geschwindigkeit der Umrandung in mm/s. Null bedeutet Verwendung der Standard-Schichtextrusionsgeschwindigkeit.", unit: "mm/s", min: 0.0, max: nil, choices: [], availableFor: [.kobraS1, .snapmakerU1], vendor: [.kobraS1: "50"]),
        SlicerOption(key: "draft_shield", page: "Sonstiges", group: "Saum", kind: .choice, title: "Windschutz (Draft Shield)", summary: "Ein Luftzug-Schutz ist nützlich, um einen ABS- oder ASA-Druck vor Verzug und dem Ablösen vom Druckbett aufgrund von Windzug zu schützen. Er wird normalerweise nur bei offenen Druckern benötigt, d.h. ohne Gehäuse.\n\nAktiviert = Umrandung ist so hoch wie das höchste gedruckte Objekt. Andernfalls wird 'Höhe der Umrandung' verwendet.\nHinweis: Mit aktiviertem Luftzug-Schutz wird die Umrandung in der Umrandungsdistanz vom Objekt gedruckt. Daher kann es bei aktiven Rändern zu Überschneidungen kommen. Um dies zu vermeiden, erhöhen Sie den Wert der Umrandungsdistanz.\n", unit: "", min: nil, max: nil, choices: [("disabled", "Nicht aktiviert"), ("enabled", "Aktiviert")], availableFor: [.kobraS1, .snapmakerU1], vendor: [.kobraS1: "disabled", .snapmakerU1: "disabled"]),
        SlicerOption(key: "brim_type", page: "Sonstiges", group: "Umrandung", kind: .choice, title: "Haftrand (Brim): Art", summary: "Dies steuert die Erstellung des Brims an der äußeren und/oder inneren Seitevon Modellen. Auto bedeutet, dass die Breite des Brims automatisch analysiert und berechnet wird.", unit: "", min: nil, max: nil, choices: [], availableFor: [.kobraS1, .snapmakerU1], vendor: [.kobraS1: "auto_brim"]),
        SlicerOption(key: "brim_width", page: "Sonstiges", group: "Umrandung", kind: .float, title: "Haftrand: Breite", summary: "Abstand vom Modell zur äußersten Randlinie", unit: "mm", min: 0.0, max: 100.0, choices: [], availableFor: [.kobraS1, .snapmakerU1], vendor: [.kobraS1: "5", .snapmakerU1: "5"]),
        SlicerOption(key: "brim_object_gap", page: "Sonstiges", group: "Umrandung", kind: .float, title: "Haftrand: Abstand zum Teil", summary: "Eine Lücke zwischen der innersten Randlinie und dem Objekt kann das Abnehmen des Randes erleichtern", unit: "mm", min: 0.0, max: 2.0, choices: [], availableFor: [.kobraS1, .snapmakerU1], vendor: [.kobraS1: "0.1", .snapmakerU1: "0.1"]),
        SlicerOption(key: "brim_ears_max_angle", page: "Sonstiges", group: "Umrandung", kind: .float, title: "Brim-Ohren: maximaler Winkel", summary: "Höchster Winkel, bei dem ein Brim-Ohr erscheinen soll.\nWenn auf 0 gesetzt, wird kein Brim erstellt.\nWenn auf etwa 180 gesetzt, wird ein Brim auf allem außer geraden Abschnitten erstellt.", unit: "", min: 0.0, max: 180.0, choices: [], availableFor: [.kobraS1, .snapmakerU1], vendor: [.kobraS1: "125"]),
        SlicerOption(key: "brim_ears_detection_length", page: "Sonstiges", group: "Umrandung", kind: .float, title: "Brim-Ohren: Erkennungslänge", summary: "Die Geometrie wird vor der Erkennung scharfer Winkel reduziert. Dieser Parameter ist ein Indikator für die minimale Länge der Abweichung für die Reduzierung.\n0 zum Deaktivieren.", unit: "mm", min: 0.0, max: nil, choices: [], availableFor: [.kobraS1, .snapmakerU1], vendor: [.kobraS1: "1"]),
        SlicerOption(key: "slicing_mode", page: "Sonstiges", group: "Spezialmodus", kind: .choice, title: "Slicing-Modus", summary: "Verwenden Sie \"Gerade-ungerade\" für 3DLabPrint-Flugzeugmodelle. Verwenden Sie \"Löcher schließen\", um alle Löcher im Modell zu schließen.", unit: "", min: nil, max: nil, choices: [("regular", "Regulär"), ("even_odd", "Gerade-ungerade"), ("close_holes", "Löcher schließen")], availableFor: [.kobraS1, .snapmakerU1], vendor: [.kobraS1: "regular"]),
        SlicerOption(key: "print_sequence", page: "Sonstiges", group: "Spezialmodus", kind: .choice, title: "Druckreihenfolge (Objekte)", summary: "Druckreihenfolge, Schicht für Schicht oder Objekt für Objekt", unit: "", min: nil, max: nil, choices: [("by layer", "Nach Ebene"), ("by object", "Nach Objekt")], availableFor: [.kobraS1, .snapmakerU1], vendor: [.kobraS1: "by layer", .snapmakerU1: "by layer"]),
        SlicerOption(key: "print_order", page: "Sonstiges", group: "Spezialmodus", kind: .choice, title: "Reihenfolge innerhalb der Schicht", summary: "Druckreihenfolge innerhalb einer einzelnen Schicht", unit: "", min: nil, max: nil, choices: [("default", "Standard"), ("as_obj_list", "Als Objektliste")], availableFor: [.kobraS1, .snapmakerU1], vendor: [.kobraS1: "default"]),
        SlicerOption(key: "spiral_mode", page: "Sonstiges", group: "Spezialmodus", kind: .bool, title: "Vasenmodus (Spiral Vase)", summary: "Glättet die Z-Bewegung der Außenkontur und macht aus einem Vollkörper einen einwandigen Druck mit festem Boden. Das Ergebnis hat keine Naht.", unit: "", min: nil, max: nil, choices: [], availableFor: [.kobraS1, .snapmakerU1], vendor: [.kobraS1: "0", .snapmakerU1: "0"]),
        SlicerOption(key: "spiral_mode_smooth", page: "Sonstiges", group: "Spezialmodus", kind: .bool, title: "Vasenmodus glätten", summary: "Die gleichmäßige Spirale glättet auch die X- und Y-Bewegungen, so dass keine Naht sichtbar ist, auch nicht in den XY-Richtungen an Wänden, die nicht senkrecht sind.", unit: "", min: nil, max: nil, choices: [], availableFor: [.kobraS1, .snapmakerU1], vendor: [.kobraS1: "0"]),
        SlicerOption(key: "spiral_mode_max_xy_smoothing", page: "Sonstiges", group: "Spezialmodus", kind: .floatOrPercent, title: "Vasenmodus: maximale XY-Glättung", summary: "Maximaler Abstand, um Punkte in XY zu verschieben, um eine glatte Spirale zu erreichen. Wenn als Prozentsatz angegeben, wird er in Bezug auf den Düsendurchmesser berechnet.", unit: "mm oder %", min: 0.0, max: 1000.0, choices: [], availableFor: [.kobraS1, .snapmakerU1], vendor: [.kobraS1: "200%"]),
        SlicerOption(key: "spiral_starting_flow_ratio", page: "Sonstiges", group: "Spezialmodus", kind: .float, title: "Vasenmodus: Fluss am Anfang", summary: "Legt das Startflussverhältnis beim Übergang von der letzten unteren Schicht zur Spirale fest. Normalerweise skaliert der Spiralenübergang das Flussverhältnis von 0% auf 100% während der ersten Schleife, was in einigen Fällen zu einer Unterextrusion am Anfang der Spirale führen kann.", unit: "", min: 0.0, max: 1.0, choices: [], availableFor: [.kobraS1, .snapmakerU1], vendor: [:]),
        SlicerOption(key: "spiral_finishing_flow_ratio", page: "Sonstiges", group: "Spezialmodus", kind: .float, title: "Vasenmodus: Fluss am Ende", summary: "Legt das Endflussverhältnis beim Beenden der Spirale fest. Normalerweise skaliert die Spiralenübergang das Flussverhältnis von 100% auf 0% während der letzten Schleife, was in einigen Fällen zu einer Unterextrusion am Ende der Spirale führen kann.", unit: "", min: 0.0, max: 1.0, choices: [], availableFor: [.kobraS1, .snapmakerU1], vendor: [:]),
        SlicerOption(key: "timelapse_type", page: "Sonstiges", group: "Spezialmodus", kind: .choice, title: "Zeitraffer-Art", summary: "Wenn der Modus \"Gleichmäßig\" oder \"Traditionell\" ausgewählt ist, wird für jeden Druck ein Zeitraffer-Video generiert. Nachdem jede Schicht gedruckt wurde, wird eine Momentaufnahme mit der Kamerakammer erstellt. Alle diese Schnappschüsse werden zu einem Zeitraffer-Video zusammengesetzt, wenn der Druck abgeschlossen ist. Wenn der Modus \"Gleichmäßig\" ausgewählt ist, bewegt sich der Druckkopf nach dem Drucken jeder Schicht zum Überschusskanal und nimmt dann eine Momentaufnahme auf. Da das geschmolzene Filament während des Aufnahmeprozesses aus der Düse austreten kann, ist ein Reinigungsturm erforderlich, damit der Druckkopf gereinigt wird.", unit: "", min: nil, max: nil, choices: [], availableFor: [.kobraS1, .snapmakerU1], vendor: [.kobraS1: "0"]),
        SlicerOption(key: "fuzzy_skin", page: "Sonstiges", group: "Spezialmodus", kind: .choice, title: "Fuzzy Skin (raue Oberfläche)", summary: "Diese Einstellung bewirkt, dass der Werkzeugkopf beim Drucken von Wänden zufällig zittert, so dass die Oberfläche ein raues, strukturiertes Aussehen erhält. Diese Einstellung steuert die Fuzzy-Position.", unit: "", min: nil, max: nil, choices: [("none", "Keine"), ("external", "Kontur"), ("all", "Kontur und Loch"), ("allwalls", "Alle Wände")], availableFor: [.kobraS1, .snapmakerU1], vendor: [.kobraS1: "none"]),
        SlicerOption(key: "fuzzy_skin_noise_type", page: "Sonstiges", group: "Spezialmodus", kind: .choice, title: "Fuzzy Skin: Rauschart", summary: "Zu verwendender Rauschtyp für die Fuzzy Skin Generierung:\nKlassisch: Klassisches, gleichmäßiges Zufallsrauschen.\nPerlin: Perlin-Rauschen, das eine konsistentere Textur liefert.\nBillow: Ähnlich wie Perlin-Rauschen, aber klumpiger.\nRidged Multifractal: Ridged-Rauschen mit scharfen, gezackten Merkmalen. Erzeugt marmorähnliche Texturen.\nVoronoi: Unterteilt die Oberfläche in Voronoi-Zellen und verschiebt jede um einen zufälligen Betrag. Erzeugt eine Patchwork-Textur.", unit: "", min: nil, max: nil, choices: [("classic", "Klassisch"), ("perlin", "Perlin"), ("billow", "Billow"), ("ridgedmulti", "Ridged Multifractal"), ("voronoi", "Voronoi")], availableFor: [.kobraS1, .snapmakerU1], vendor: [:]),
        SlicerOption(key: "fuzzy_skin_point_distance", page: "Sonstiges", group: "Spezialmodus", kind: .float, title: "Fuzzy Skin: Punktabstand", summary: "Der durchschnittliche Abstand zwischen den auf jedem Linienabschnitt eingeführten Zufallspunkten", unit: "mm", min: 0.0, max: 5.0, choices: [], availableFor: [.kobraS1, .snapmakerU1], vendor: [.kobraS1: "0.8"]),
        SlicerOption(key: "fuzzy_skin_thickness", page: "Sonstiges", group: "Spezialmodus", kind: .float, title: "Fuzzy Skin: Stärke", summary: "Die Breite, innerhalb der gezittert werden soll. Sie sollte unter der Breite der Außenwandlinie liegen.", unit: "mm", min: 0.0, max: 1.0, choices: [], availableFor: [.kobraS1, .snapmakerU1], vendor: [.kobraS1: "0.3"]),
        SlicerOption(key: "fuzzy_skin_scale", page: "Sonstiges", group: "Spezialmodus", kind: .float, title: "Fuzzy Skin: Strukturgröße", summary: "Die Grundgröße der kohärenten Rauschstrukturen in mm. Höhere Werte führen zu größeren Strukturen.", unit: "", min: 0.1, max: 500.0, choices: [], availableFor: [.kobraS1, .snapmakerU1], vendor: [:]),
        SlicerOption(key: "fuzzy_skin_octaves", page: "Sonstiges", group: "Spezialmodus", kind: .int, title: "Fuzzy Skin: Rausch-Oktaven", summary: "Die Anzahl der zu verwendenden Oktaven des kohärenten Rauschens. Höhere Werte erhöhen den Detailgrad des Rauschens, verlängern aber auch die Berechnungszeit.", unit: "", min: 1.0, max: 10.0, choices: [], availableFor: [.kobraS1, .snapmakerU1], vendor: [:]),
        SlicerOption(key: "fuzzy_skin_persistence", page: "Sonstiges", group: "Spezialmodus", kind: .float, title: "Fuzzy Skin: Rausch-Persistenz", summary: "Die Abklingrate für höhere Oktaven des kohärenten Rauschens. Niedrigere Werte führen zu glatterem Rauschen.", unit: "", min: 0.01, max: 1.0, choices: [], availableFor: [.kobraS1, .snapmakerU1], vendor: [:]),
        SlicerOption(key: "fuzzy_skin_first_layer", page: "Sonstiges", group: "Spezialmodus", kind: .bool, title: "Fuzzy Skin auch in der ersten Schicht", summary: "Ob Fuzzy Skin auf die erste Schicht angewendet werden soll.", unit: "", min: nil, max: nil, choices: [], availableFor: [.kobraS1, .snapmakerU1], vendor: [.kobraS1: "0"]),
        SlicerOption(key: "reduce_infill_retraction", page: "Sonstiges", group: "G-Code-Ausgabe", kind: .bool, title: "Rückzüge (Retract) in der Füllung vermeiden", summary: "Kein Rückzug, wenn die Leerfahrt komplett im Füllungsbereich liegt. Dadurch sieht man kein Fädenziehen, spart Rückzüge und Zeit, verlängert aber die Slicing-Zeit.", unit: "", min: nil, max: nil, choices: [], availableFor: [.kobraS1, .snapmakerU1], vendor: [.kobraS1: "1", .snapmakerU1: "1"]),
        SlicerOption(key: "gcode_add_line_number", page: "Sonstiges", group: "G-Code-Ausgabe", kind: .bool, title: "Zeilennummern im G-Code", summary: "Aktivieren Sie diese Option, um die Zeilennummer (Nx) am Anfang jeder G-Code-Zeile einzufügen.", unit: "", min: nil, max: nil, choices: [], availableFor: [.kobraS1, .snapmakerU1], vendor: [.kobraS1: "0"]),
        SlicerOption(key: "gcode_comments", page: "Sonstiges", group: "G-Code-Ausgabe", kind: .bool, title: "Ausführlicher G-Code (Kommentare)", summary: "Aktivieren Sie diese Option, um eine kommentierte G-Code-Datei zu erhalten, in der jede Zeile durch einen beschreibenden Text erklärt wird. Wenn Sie von der SD-Karte drucken, kann das zusätzliche Gewicht der Datei dazu führen, dass Ihre Firmware langsamer wird.", unit: "", min: nil, max: nil, choices: [], availableFor: [.kobraS1, .snapmakerU1], vendor: [.kobraS1: "0"]),
        SlicerOption(key: "gcode_label_objects", page: "Sonstiges", group: "G-Code-Ausgabe", kind: .bool, title: "Objekte im G-Code beschriften", summary: "Schreibt Kommentare in den G-Code, zu welchem Objekt jede Bewegung gehört. Nützlich für „Objekt abbrechen“ (OctoPrint-CancelObject). Nicht kompatibel mit Single-Extruder-Multi-Material.", unit: "", min: nil, max: nil, choices: [], availableFor: [.kobraS1, .snapmakerU1], vendor: [.kobraS1: "1"]),
        SlicerOption(key: "exclude_object", page: "Sonstiges", group: "G-Code-Ausgabe", kind: .bool, title: "Objekt ausschließen (Exclude Object)", summary: "Aktivieren Sie diese Option, um den Befehl EXCLUDE OBJECT im G-Code hinzuzufügen.", unit: "", min: nil, max: nil, choices: [], availableFor: [.kobraS1, .snapmakerU1], vendor: [.kobraS1: "1", .snapmakerU1: "1"]),
        SlicerOption(key: "fill_multiline", page: "Festigkeit", group: "Füllung", kind: .int, title: "Mehrfach-Füllungslinien", summary: "Verwendung mehrerer Linien für das Füllmuster, sofern dies vom Füllmuster unterstützt wird.", unit: "", min: 1.0, max: 5.0, choices: [], availableFor: [.snapmakerU1], vendor: [:]),
        SlicerOption(key: "sparse_infill_rotate_template", page: "Festigkeit", group: "Füllung", kind: .text, title: "Füllung: Drehvorlage", summary: "Drehen Sie die Richtung der spärlichen Füllung pro Schicht mit einer Vorlage von Winkeln. Geben Sie durch Kommas getrennte Grad ein (z.B. '0,30,60,90'). Winkel werden schichtweise in der Reihenfolge angewendet und wiederholt, wenn die Liste endet. Erweiterte Syntax wird unterstützt: '+5' dreht +5° jede Schicht; '+5#5' dreht +5° alle 5 Schichten. Siehe das Wiki für Details. Wenn eine Vorlage festgelegt ist, wird die Standardfüllrichtungseinstellung ignoriert. Beachten Sie: Einige Füllmuster (z.B. Gyroid) steuern die Rotation selbst; verwenden Sie sie mit Vorsicht.", unit: "°", min: nil, max: nil, choices: [], availableFor: [.snapmakerU1], vendor: [:]),
        SlicerOption(key: "skin_infill_density", page: "Festigkeit", group: "Füllung", kind: .percent, title: "Dichte der Außenhaut-Füllung", summary: "Der Teil der äußeren Oberfläche des Modells innerhalb eines bestimmten Tiefenbereichs wird als Haut bezeichnet. Dieser Parameter wird verwendet, um die Dichte dieses Abschnitts anzupassen.Wenn zwei Regionen die gleichen spärlichen Füllungseinstellungen, aber unterschiedliche Hautdichten aufweisen, wird dieser Bereich nicht in zwei separate Regionen aufgeteilt.", unit: "", min: 0.0, max: 100.0, choices: [], availableFor: [.snapmakerU1], vendor: [:]),
        SlicerOption(key: "skeleton_infill_density", page: "Festigkeit", group: "Füllung", kind: .percent, title: "Dichte der Kern-Füllung", summary: "Der verbleibende Teil des Modellkonturs nach dem Entfernen einer bestimmten Tiefe von der Oberfläche wird als Skelett bezeichnet. Dieser Parameter wird verwendet, um die Dichte dieses Abschnitts anzupassen.Wenn zwei Regionen die gleichen spärlichen Füllungseinstellungen, aber unterschiedliche Skelettdichten aufweisen, werden sich ihre Skelettbereiche überlappen.", unit: "", min: 0.0, max: 100.0, choices: [], availableFor: [.snapmakerU1], vendor: [:]),
        SlicerOption(key: "infill_lock_depth", page: "Festigkeit", group: "Füllung", kind: .float, title: "Verriegelungstiefe der Füllung", summary: "Der Parameter legt die Überlappungstiefe zwischen Innenraum und Außenhaut fest.", unit: "mm", min: 0.0, max: 100.0, choices: [], availableFor: [.snapmakerU1], vendor: [:]),
        SlicerOption(key: "skin_infill_depth", page: "Festigkeit", group: "Füllung", kind: .float, title: "Tiefe der Außenhaut-Füllung", summary: "Der Parameter legt die Hauttiefe fest.", unit: "mm", min: 0.0, max: 100.0, choices: [], availableFor: [.snapmakerU1], vendor: [:]),
        SlicerOption(key: "skin_infill_line_width", page: "Festigkeit", group: "Füllung", kind: .floatOrPercent, title: "Linienbreite Außenhaut-Füllung", summary: "Passt die Linienbreite der ausgewählten Hautpfade an.", unit: "mm", min: 0.0, max: nil, choices: [], availableFor: [.snapmakerU1], vendor: [:]),
        SlicerOption(key: "skeleton_infill_line_width", page: "Festigkeit", group: "Füllung", kind: .floatOrPercent, title: "Linienbreite Kern-Füllung", summary: "Passt die Linienbreite der ausgewählten Skelettpfade an.", unit: "mm", min: 0.0, max: nil, choices: [], availableFor: [.snapmakerU1], vendor: [:]),
        SlicerOption(key: "symmetric_infill_y_axis", page: "Festigkeit", group: "Füllung", kind: .bool, title: "Füllung symmetrisch zur Y-Achse", summary: "Wenn das Modell zwei Teile hat, die symmetrisch zur Y-Achse sind, und Sie möchten, dass diese Teile symmetrische Texturen haben, klicken Sie bitte auf diese Option auf einem der Teile.", unit: "", min: nil, max: nil, choices: [], availableFor: [.snapmakerU1], vendor: [:]),
        SlicerOption(key: "infill_shift_step", page: "Festigkeit", group: "Füllung", kind: .float, title: "Füllung: Versatz pro Schicht", summary: "Dieser Parameter fügt jeder Schicht der Füllung eine leichte Verschiebung hinzu, um eine Kreuztextur zu erzeugen.", unit: "mm", min: 0.0, max: 10.0, choices: [], availableFor: [.snapmakerU1], vendor: [:]),
        SlicerOption(key: "lateral_lattice_angle_1", page: "Festigkeit", group: "Füllung", kind: .float, title: "Gitterwinkel 1", summary: "Der Winkel des ersten Satzes von 2D-Gitterelementen in der Z-Richtung. Null ist vertikal.", unit: "", min: -75.0, max: 75.0, choices: [], availableFor: [.snapmakerU1], vendor: [:]),
        SlicerOption(key: "lateral_lattice_angle_2", page: "Festigkeit", group: "Füllung", kind: .float, title: "Gitterwinkel 2", summary: "Der Winkel des zweiten Satzes von 2D-Gitterelementen in der Z-Richtung. Null ist vertikal.", unit: "", min: -75.0, max: 75.0, choices: [], availableFor: [.snapmakerU1], vendor: [:]),
        SlicerOption(key: "infill_overhang_angle", page: "Festigkeit", group: "Füllung", kind: .float, title: "Überhangwinkel der Füllung", summary: "Der Winkel der schrägen Linien der Füllung. 60° führt zu einer reinen Wabenstruktur.", unit: "", min: 15.0, max: 75.0, choices: [], availableFor: [.snapmakerU1], vendor: [:]),
        SlicerOption(key: "solid_infill_rotate_template", page: "Festigkeit", group: "Füllung", kind: .text, title: "Vollfüllung: Drehvorlage", summary: "Dieser Parameter fügt jeder Schicht der massiven Füllung eine Rotation hinzu, um eine Kreuzstruktur zu erzeugen.Die Vorlage ist eine durch Kommas getrennte Liste von Winkeln in Grad, z.B. '0,90'. Der erste Winkel wird auf die erste Schicht angewendet, der zweite Winkel auf die zweite Schicht usw. Wenn es mehr Schichten als Winkel gibt, werden die Winkel wiederholt. Beachten Sie, dass nicht alle massiven Füllmuster eine Rotation unterstützen.", unit: "", min: nil, max: nil, choices: [], availableFor: [.snapmakerU1], vendor: [:]),
        SlicerOption(key: "align_infill_direction_to_model", page: "Festigkeit", group: "Erweiterte Einstellungen", kind: .bool, title: "Füllrichtung am Modell ausrichten", summary: "Richtet die Füll- und Oberflächenfüllrichtungen so aus, dass sie der Orientierung des Modells auf der Bauplatte folgen. Wenn aktiviert, rotieren die Füllrichtungen mit dem Modell, um optimale Festigkeitseigenschaften zu erhalten.", unit: "", min: nil, max: nil, choices: [], availableFor: [.snapmakerU1], vendor: [:]),
        SlicerOption(key: "extra_solid_infills", page: "Festigkeit", group: "Erweiterte Einstellungen", kind: .text, title: "Zusätzliche Vollfüllungs-Schichten", summary: "Fügt an bestimmten Schichten massive Füllung ein. Verwenden Sie N, um jede N-te Schicht einzufügen, N#K, um K aufeinanderfolgende massive Schichten alle N Schichten einzufügen (K ist optional, z.B. '5#' entspricht '5#1'), oder eine kommagetrennte Liste (z.B. 1,7,9), um sie in expliziten Schichten einzufügen. Schichten sind 1-basiert.", unit: "", min: nil, max: nil, choices: [], availableFor: [.snapmakerU1], vendor: [:]),
        SlicerOption(key: "default_junction_deviation", page: "Geschwindigkeit", group: "Jerk(XY)", kind: .float, title: "Junction Deviation (Ecken-Toleranz)", summary: "Marlin Firmware Junction Deviation (ersetzt die traditionelle XY-Ruckeinstellung)", unit: "", min: 0.0, max: nil, choices: [], availableFor: [.snapmakerU1], vendor: [:]),
        SlicerOption(key: "support_ironing", page: "Stützen", group: "Stützglättung", kind: .bool, title: "Bügeln der Support-Kontaktschicht", summary: "Glättung verwendet eine kleine Flussmenge, um auf derselben Höhe der Stützstruktur-Schnittstelle erneut zu drucken, um sie glatter zu machen. Diese Einstellung steuert, ob die Stützstruktur-Schnittstelle geglättet wird. Wenn aktiviert, wird die Stützstruktur-Schnittstelle ebenfalls als massiv extrudiert.", unit: "", min: nil, max: nil, choices: [], availableFor: [.snapmakerU1], vendor: [:]),
        SlicerOption(key: "support_ironing_pattern", page: "Stützen", group: "Stützglättung", kind: .choice, title: "Support-Bügeln: Muster", summary: "Das Muster, das beim Glätten verwendet wird", unit: "", min: nil, max: nil, choices: [("rectilinear", "Geradlinig"), ("concentric", "Konzentrisch")], availableFor: [.snapmakerU1], vendor: [:]),
        SlicerOption(key: "support_ironing_flow", page: "Stützen", group: "Stützglättung", kind: .percent, title: "Support-Bügeln: Fluss", summary: "Die Menge an Material, die während des Glättens extrudiert wird. Relativ zum Fluss der normalen Stützstruktur-Schichthöhe. Ein zu hoher Wert führt zu Überextrusion auf der Oberfläche.", unit: "", min: 0.0, max: 100.0, choices: [], availableFor: [.snapmakerU1], vendor: [:]),
        SlicerOption(key: "support_ironing_spacing", page: "Stützen", group: "Stützglättung", kind: .float, title: "Support-Bügeln: Linienabstand", summary: "Der Abstand zwischen den Linien beim Glätten", unit: "mm", min: 0.0, max: 1.0, choices: [], availableFor: [.snapmakerU1], vendor: [:]),
        SlicerOption(key: "prime_tower_brim_chamfer", page: "Mehrfarben", group: "Reinigungsturm", kind: .bool, title: "Rand abschrägen", summary: "Reduziert den Rand um den Reinigungsturm Schicht für Schicht. Spart Material, die Haftung der ersten Schicht bleibt erhalten.", unit: "", min: nil, max: nil, choices: [], availableFor: [.snapmakerU1], vendor: [:]),
        SlicerOption(key: "prime_tower_brim_chamfer_max_width", page: "Mehrfarben", group: "Reinigungsturm", kind: .float, title: "Maximale Breite der Abschrägung", summary: "Maximale Breite der Abschrägungszone ab der Turmwand. Größer = sanfterer Verlauf, braucht aber mehr Schichten.", unit: "mm", min: 0.0, max: nil, choices: [], availableFor: [.snapmakerU1], vendor: [:]),
        SlicerOption(key: "wipe_tower_wall_type", page: "Mehrfarben", group: "Reinigungsturm", kind: .choice, title: "Reinigungsturm: Wandart", summary: "Wandtyp des Reinigungsturms.\n1. Rechteck: Der Standard-Wandtyp, ein Rechteck mit fester Breite und Höhe.\n2. Kegel: Ein Kegel mit einer Fase am Boden, um den Reinigungsturm zu stabilisieren.\n3. Rippe: Fügt der Turmwand vier Rippen für verbesserte Stabilität hinzu.", unit: "", min: nil, max: nil, choices: [], availableFor: [.snapmakerU1], vendor: [.snapmakerU1: "rib"]),
        SlicerOption(key: "wipe_tower_extra_rib_length", page: "Mehrfarben", group: "Reinigungsturm", kind: .float, title: "Reinigungsturm: zusätzliche Rippenlänge", summary: "Positive Werte können die Größe der Rippenwand erhöhen, während negative Werte die Größe verringern können. Die Größe der Rippenwand kann jedoch nicht kleiner sein als die, die durch das Reinigungsvolumen bestimmt wird.", unit: "mm", min: nil, max: 300.0, choices: [], availableFor: [.snapmakerU1], vendor: [.snapmakerU1: "0"]),
        SlicerOption(key: "wipe_tower_rib_width", page: "Mehrfarben", group: "Reinigungsturm", kind: .float, title: "Reinigungsturm: Rippenbreite", summary: "Rippenweite", unit: "mm", min: 0.0, max: nil, choices: [], availableFor: [.snapmakerU1], vendor: [:]),
        SlicerOption(key: "wipe_tower_fillet_wall", page: "Mehrfarben", group: "Reinigungsturm", kind: .bool, title: "Reinigungsturm: ausgerundete Wand", summary: "Die Wand des Reinigungsturms wird abgerundet.", unit: "", min: nil, max: nil, choices: [], availableFor: [.snapmakerU1], vendor: [:]),
        SlicerOption(key: "wipe_tower_wall_gap", page: "Mehrfarben", group: "Reinigungsturm", kind: .bool, title: "Lücke in der Turmwand", summary: "Erzeugt kleine Lücken in der Außenwand des Reinigungsturms an den Werkzeugwechsel-Eintrittspunkten. Der Filament-Klecks landet so an der Lückenkante statt auf der Wand.", unit: "", min: nil, max: nil, choices: [], availableFor: [.snapmakerU1], vendor: [:]),
        SlicerOption(key: "delta_temperature", page: "Mehrfarben", group: "Ooze-Prävention", kind: .int, title: "Vorheiz-Temperaturdifferenz", summary: "Legt die Vorheiztemperatur fest. Beispiel: Zieltemperatur 220 °C und Differenz −30 °C → Vorheizen auf 190 °C.", unit: "", min: -50.0, max: 50.0, choices: [], availableFor: [.snapmakerU1], vendor: [:]),
        SlicerOption(key: "dithering_local_z_mode", page: "Mehrfarben", group: "Farbmischung (experimentell)", kind: .bool, title: "Mischschicht unterteilen", summary: "Unterteilt die Schichthöhe in Mischbereichen für bessere Farbmischung (experimentell).", unit: "", min: nil, max: nil, choices: [], availableFor: [.snapmakerU1], vendor: [:]),
        SlicerOption(key: "dithering_local_z_whole_objects", page: "Mehrfarben", group: "Farbmischung (experimentell)", kind: .bool, title: "Gesamter Bereich", summary: "Experimentell: Wendet die Z-Unterteilung auf ganze Mischfarbbereiche an, nicht nur auf bemalte Mischmasken. Nur mit „Mischschicht unterteilen“ verfügbar.", unit: "", min: nil, max: nil, choices: [], availableFor: [.snapmakerU1], vendor: [:]),
        SlicerOption(key: "dithering_local_z_infill", page: "Mehrfarben", group: "Farbmischung (experimentell)", kind: .bool, title: "Unterteilung auch auf Füllung anwenden", summary: "Experimentell: Wendet die Unterteilung auch auf die Füllung in Mischbereichen an. Verbessert die Farbmischung innen, kann aber mehr Werkzeugwechsel verursachen.", unit: "", min: nil, max: nil, choices: [], availableFor: [.snapmakerU1], vendor: [:]),
        SlicerOption(key: "single_loop_draft_shield", page: "Sonstiges", group: "Saum", kind: .bool, title: "Windschutz: nur eine Linie nach der ersten Schicht", summary: "Begrenzt die Umrandungs- / Luftzug-Schutz-Schleifen auf eine Wand nach der ersten Schicht. Dies ist nützlich, um Filament zu sparen, kann jedoch dazu führen, dass der Luftzug-Schutz / die Umrandung verzieht oder bricht.", unit: "", min: nil, max: nil, choices: [], availableFor: [.snapmakerU1], vendor: [:]),
        SlicerOption(key: "fuzzy_skin_mode", page: "Sonstiges", group: "Fuzzy Skin", kind: .choice, title: "Fuzzy Skin: Erzeugungsmodus", summary: "Fuzzy Skin Generierungsmodus. Funktioniert nur mit Arachne!\nVerschiebung: Klassischer Modus, bei dem das Muster durch Verschieben der Düse seitlich vom ursprünglichen Pfad gebildet wird.\n Extrusion: Der Modus, bei dem das Muster durch die Menge des extrudierten Plastiks gebildet wird. Dies ist der schnelle und gerade Algorithmus ohne unnötiges Zittern der Düse, der ein glattes Muster ergibt. Aber esist nützlicher, um lockere Wände in der gesamten Array zu bilden.\nKombiniert: Gemeinsamer Modus [Verschiebung] + [Extrusion]. Das Aussehen der Wände ist ähnlich wie im Modus [Verschiebung], aber es hinterlässt keine Poren zwischen den Perimetern.\n\nAchtung! Die Modi [Extrusion] und [Kombiniert] funktionieren nur, wenn die fuzzy_skin_thickness-Parameter nicht dicker als die Dicke der gedruckten Schleife ist. Gleichzeitig sollte die Breite der Extrusion für eine bestimmte Schicht auch nicht unter einem bestimmten Niveau liegen. Normalerweise beträgt sie 15-25% der Schichthöhe. Daher beträgt die maximale Fuzzy Skin Dicke bei einer Perimeterbreite von 0,4 mm und einer Schichthöhe von 0,2 mm 0,4-(0,2*0,25)=±0,35 mm! Wenn Sie einen höheren Parameter als diesen eingeben, wird der Fehler Flow::spacing() angezeigt, und das Modell wird nicht gesliced. Sie können diese Zahl wählen, bis dieser Fehler wiederholt wird. ", unit: "", min: nil, max: nil, choices: [("displacement", "Verschiebung"), ("extrusion", "Extrusion"), ("combined", "Kombiniert")], availableFor: [.snapmakerU1], vendor: [:]),
    ]
}
